import { FunctionDeclaration, Schema, Type } from "@google/genai";

// --- Chat Types ---

export interface Message {
  id: string;
  role: 'user' | 'model' | 'system';
  content: string;
  timestamp: Date;
  isThinking?: boolean;
  toolCalls?: ToolCallDetails[];
}

export interface ToolCallDetails {
  functionName: string;
  args: Record<string, any>;
  result?: any;
}

// --- CrowdStrike Domain Types ---

export interface Incident {
  incident_id: string;
  title: string;
  description: string;
  severity: 'Critical' | 'High' | 'Medium' | 'Low';
  status: 'New' | 'In Progress' | 'Closed';
  created_timestamp: string;
  host_id: string;
  host_name: string;
}

export interface Device {
  device_id: string;
  hostname: string;
  platform_name: string;
  os_version: string;
  status: 'normal' | 'contained' | 'compromised';
  last_seen: string;
  external_ip: string;
}

export interface Detection {
  detection_id: string;
  tactic: string;
  technique: string;
  severity: string;
  timestamp: string;
  cmd_line: string;
}

// --- Config Types ---

export interface AppConfig {
  clientId: string;
  clientSecret: string;
  baseUrl: string; // e.g., https://api.us-2.crowdstrike.com
  useSimulation: boolean;
}

import { FunctionDeclaration, Type } from "@google/genai";

export const SYSTEM_INSTRUCTION = `
You are FalconAI, an elite automated security operations agent integrated with the CrowdStrike Falcon platform.
Your mission is to assist security analysts by investigating incidents, managing devices, and explaining threats.

GUIDELINES:
1. **Be Concise**: Security analysts are busy. Give direct answers.
2. **Use Tools**: You have access to tools to query CrowdStrike. ALWAYS use tools to get real-time data instead of guessing.
3. **Format Output**: Use Markdown. Use tables for lists of incidents or devices. 
4. **Safety First**: If asked to perform a disruptive action (like containing a host), explicitly state what you are doing.

AVAILABLE DATA:
- Incidents: Security events requiring attention.
- Devices (Hosts): Endpoints protected by Falcon.
- Detections: Specific alerts or IOAs (Indicators of Attack).
`;

// Tool Definitions for Gemini

