import { AppConfig, Incident, Device, Detection } from '../types';

// Mock Data Generators for Simulation Mode
const generateMockIncidents = (count: number, severityFilter?: string): Incident[] => {
  const severities = ['Critical', 'High', 'Medium', 'Low'];
  const statuses = ['New', 'In Progress', 'Closed'];
  const types = ['Ransomware Detected', 'Lateral Movement', 'Credential Dumping', 'Malicious Script'];

  return Array.from({ length: count }).map((_, i) => ({
    incident_id: `inc-${202400 + i}`,
    title: types[Math.floor(Math.random() * types.length)],
    description: `Suspicious activity detected on endpoint matching known threat patterns.`,
    severity: (severityFilter || severities[Math.floor(Math.random() * severities.length)]) as any,
    status: statuses[Math.floor(Math.random() * statuses.length)] as any,
    created_timestamp: new Date(Date.now() - Math.floor(Math.random() * 1000000000)).toISOString(),
    host_id: `aid-${1000 + i}`,
    host_name: `DESKTOP-US-${100 + i}`
  }));
};

const mockDevices: Device[] = [
  { device_id: 'aid-1000', hostname: 'CEO-LAPTOP', platform_name: 'Windows', os_version: 'Win11 22H2', status: 'normal', last_seen: new Date().toISOString(), external_ip: '192.168.1.50' },
  { device_id: 'aid-1001', hostname: 'FINANCE-SRV-01', platform_name: 'Windows', os_version: 'Server 2019', status: 'compromised', last_seen: new Date().toISOString(), external_ip: '10.0.0.5' },
  { device_id: 'aid-1002', hostname: 'DEV-MACBOOK', platform_name: 'Mac', os_version: 'Sonoma 14.2', status: 'normal', last_seen: new Date().toISOString(), external_ip: '172.16.0.23' },
];

export class CrowdStrikeService {
  private config: AppConfig;

  constructor(config: AppConfig) {
    this.config = config;
  }

  // --- Tool Implementations ---

  async list_incidents(args: { severity?: string; limit?: number }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 800)); // Simulate latency
      return generateMockIncidents(args.limit || 5, args.severity);
    }
    // Real API implementation would go here (Fetch request to /incidents/queries/incidents/v1)
    return { error: "Real API calls require a proxy server due to browser CORS policies. Please enable Simulation Mode." };
  }

  async get_device_details(args: { identifier: string }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 600));
      const device = mockDevices.find(d => 
        d.device_id.toLowerCase() === args.identifier.toLowerCase() || 
        d.hostname.toLowerCase() === args.identifier.toLowerCase()
      );
      if (device) return device;
      return { error: `Device '${args.identifier}' not found.` };
    }
    return { error: "Real API disabled in browser environment." };
  }

  async contain_host(args: { device_id: string }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 1500)); // Action takes longer
      const device = mockDevices.find(d => d.device_id === args.device_id);
      if (device) {
        device.status = 'contained';
        return { success: true, message: `Host ${args.device_id} has been successfully contained. Network access restricted.` };
      }
      return { error: `Device ${args.device_id} not found.` };
    }
    return { error: "Real API disabled in browser environment." };
  }

  async lift_containment(args: { device_id: string }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 1500));
      const device = mockDevices.find(d => d.device_id === args.device_id);
      if (device) {
        device.status = 'normal';
        return { success: true, message: `Containment lifted for host ${args.device_id}. Network access restored.` };
      }
      return { error: `Device ${args.device_id} not found.` };
    }
    return { error: "Real API disabled in browser environment." };
  }

  async get_detections(args: { host_id?: string; limit?: number }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 800));
      const detections: Detection[] = [
        { detection_id: 'det-1', tactic: 'Execution', technique: 'Command and Scripting Interpreter', severity: 'High', timestamp: new Date().toISOString(), cmd_line: 'powershell.exe -enc ...' },
        { detection_id: 'det-2', tactic: 'Persistence', technique: 'Registry Run Keys', severity: 'Medium', timestamp: new Date().toISOString(), cmd_line: 'reg add HKLM\\...' }
      ];
      return detections;
    }
    return { error: "Real API disabled in browser environment." };
  }
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { TOOLS, SYSTEM_INSTRUCTION } from "../constants";
import { AppConfig, Message, ToolCallDetails } from "../types";
import { CrowdStrikeService } from "./crowdstrikeService";

export class AgentController {
  private genAI: GoogleGenAI;
  private chat: Chat;
  private csService: CrowdStrikeService;

  constructor(apiKey: string, config: AppConfig) {
    this.genAI = new GoogleGenAI({ apiKey });
    this.csService = new CrowdStrikeService(config);

    this.chat = this.genAI.chats.create({
      model: 'gemini-2.5-flash',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{ functionDeclarations: TOOLS }],
      }
    });
  }

  async processMessage(userMessage: string, onUpdate: (msg: Message) => void): Promise<void> {
    try {
      // 1. Send user message
      let response = await this.chat.sendMessage({ message: userMessage });

      // 2. Loop to handle potential multiple tool calls
      while (response.functionCalls && response.functionCalls.length > 0) {
        const functionCalls = response.functionCalls;

        // Notify UI about tool usage
        const toolDetails: ToolCallDetails[] = functionCalls.map(fc => ({
          functionName: fc.name,
          args: fc.args as Record<string, any>
        }));

        onUpdate({
            id: crypto.randomUUID(),
            role: 'model',
            content: '', // Temporary empty content while executing
            timestamp: new Date(),
            isThinking: true,
            toolCalls: toolDetails
        });

        // Execute Tools
        const functionResponses = await Promise.all(
            functionCalls.map(async (call) => {
                let result;
                try {
                    switch (call.name) {
                        case 'list_incidents':
                            result = await this.csService.list_incidents(call.args as any);
                            break;
                        case 'get_device_details':
                            result = await this.csService.get_device_details(call.args as any);
                            break;
                        case 'contain_host':
                            result = await this.csService.contain_host(call.args as any);
                            break;
                        case 'lift_containment':
                            result = await this.csService.lift_containment(call.args as any);
                            break;
                        case 'get_detections':
                            result = await this.csService.get_detections(call.args as any);
                            break;
                        default:
                            result = { error: 'Unknown tool' };
                    }
                } catch (e: any) {
                    result = { error: e.message };
                }
                return {
                    id: call.id,
                    name: call.name,
                    response: { result: result }
                };
            })
        );

        // 3. Send Tool Results back to Gemini
        response = await this.chat.sendMessage({
            message: functionResponses // Pass the array of responses
        });
      }

      // 4. Final Text Response
      onUpdate({
        id: crypto.randomUUID(),
        role: 'model',
        content: response.text || "No response generated.",
        timestamp: new Date(),
        isThinking: false
      });

    } catch (error: any) {
      console.error("Agent Error:", error);
      onUpdate({
        id: crypto.randomUUID(),
        role: 'system',
        content: `Error: ${error.message || 'An unexpected error occurred.'}`,
        timestamp: new Date(),
        isThinking: false
      });
    }
  }
}

