import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `**FalconAI Online.** 

I am connected to your CrowdStrike Falcon instance. I can help you:
- Investigate security incidents
- Analyze host/device details
- Contain compromised hosts
- Review detection telemetry

How can I assist with your security operations today?`,
  timestamp: new Date()
};

export default function App() {
  // State
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Configuration
  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
    useSimulation: true
  });

  // Refs
  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Initialize Agent
  useEffect(() => {
    // Only init if we have the Gemini API Key from environment
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isProcessing || !agentRef.current) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      await agentRef.current.processMessage(input, (updatedMsg) => {
        setMessages(prev => {
            // Check if this message ID already exists (updating a stream/tool call)
            const exists = prev.find(m => m.id === updatedMsg.id);
            if (exists) {
                return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
            }
            return [...prev, updatedMsg];
        });
      });
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

