  private token: string | null = null;
  private tokenExpiry: number = 0;

  constructor(config: AppConfig) {
    this.config = config;
  }

  // --- Auth Helper ---

  private async getAccessToken(): Promise<string> {
    if (this.token && Date.now() < this.tokenExpiry) {
      return this.token;
    }

    // Prepare Auth Request
    const body = new URLSearchParams();
    body.append('client_id', this.config.clientId);
    body.append('client_secret', this.config.clientSecret);

    try {
      const response = await fetch(`${this.config.baseUrl}/oauth2/token`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body
      });

      if (!response.ok) {
        const errText = await response.text();
        throw new Error(`Authentication Failed (${response.status}): ${errText}`);
      }

      const data = await response.json();
      this.token = data.access_token;
      // Expires in seconds, convert to ms, subtract 1 minute buffer
      this.tokenExpiry = Date.now() + (data.expires_in * 1000) - 60000;
      return this.token!;
    } catch (e: any) {
      // Often blocked by CORS in pure browser environments
      if (e.message && e.message.includes('Failed to fetch')) {
        throw new Error("Network Error: Could not connect to CrowdStrike API. This is likely a CORS issue. Real API calls usually require a backend proxy.");
      }
      throw e;
    }
  }

  private async fetchAPI(endpoint: string, method: string = 'GET', body?: any) {
    const token = await this.getAccessToken();

    const response = await fetch(`${this.config.baseUrl}${endpoint}`, {
      method,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: body ? JSON.stringify(body) : undefined
    });

    if (!response.ok) {
      const errText = await response.text();
      // Handle CS Errors
      let errMsg = `API Error ${response.status}`;
      try {
         const jsonErr = JSON.parse(errText);
         if (jsonErr.errors && jsonErr.errors.length > 0) {
             errMsg += `: ${jsonErr.errors[0].message}`;
         }
      } catch {}
      throw new Error(errMsg);
    }

    return response.json();
  }

  // --- Tool Implementations ---

  async list_incidents(args: { severity?: string; limit?: number }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return generateMockIncidents(args.limit || 5, args.severity);
    }

    // Helper to map severity string to codes
    const getSeverityCode = (sev?: string) => sev === 'Critical' ? 80 : sev === 'High' ? 60 : sev === 'Medium' ? 40 : 20;

    try {
      // 1. Try fetching actual Incidents first
      let filter = "";
      if (args.severity) {
         filter = `&filter=severity_code:>=${getSeverityCode(args.severity)}`;
      }

      const queryUrl = `/incidents/queries/incidents/v1?limit=${args.limit || 5}&sort=created_timestamp.desc${filter}`;
      const queryRes = await this.fetchAPI(queryUrl);
      const ids = queryRes.resources;

      if (!ids || ids.length === 0) return [];

      const detailsRes = await this.fetchAPI(`/incidents/entities/incidents/GET/v1`, 'POST', { ids });

      return detailsRes.resources.map((inc: any) => ({
         incident_id: inc.incident_id,
         title: inc.name || `Incident ${inc.incident_id}`,
         description: inc.description || "No description provided",
         severity: inc.severity_code >= 80 ? 'Critical' : inc.severity_code >= 60 ? 'High' : inc.severity_code >= 40 ? 'Medium' : 'Low',
         status: inc.status === 20 ? 'New' : inc.status === 30 ? 'In Progress' : 'Closed',
         created_timestamp: inc.created_timestamp,
         host_id: inc.primary_module ? 'N/A' : (inc.hosts?.[0]?.device_id || 'Unknown'),
         host_name: 'Lookup Required'
      }));

    } catch (e: any) {
      // 2. FALLBACK: If Incidents API fails (e.g. 403 Forbidden because 'Incidents' scope missing),
      // fetch Detections instead and map them to appear as Incidents to the user.
      console.warn("Incidents API failed, falling back to Detections:", e.message);

      try {
        let detFilter = "";
        if (args.severity) {
            detFilter = `&filter=max_severity:>=${getSeverityCode(args.severity)}`;
        }

        // Query Detections
        const detQueryRes = await this.fetchAPI(`/detects/queries/detects/v1?limit=${args.limit || 5}&sort=created_timestamp.desc${detFilter}`);
        const detIds = detQueryRes.resources;

        if (!detIds || detIds.length === 0) return [];

        // Get Detection Details
        const detDetailsRes = await this.fetchAPI(`/detects/entities/summaries/GET/v1`, 'POST', { ids: detIds });

        return detDetailsRes.resources.map((d: any) => ({
            incident_id: d.detection_id, // Map ID
            title: `[Detection] ${d.tactic || 'Unknown'} - ${d.technique || 'Activity'}`, // Map Title
            description: d.behaviors?.[0]?.cmdline ? `Command: ${d.behaviors[0].cmdline}` : "Detection triggered on host.",
            severity: d.max_severity >= 80 ? 'Critical' : d.max_severity >= 60 ? 'High' : d.max_severity >= 40 ? 'Medium' : 'Low',
            status: d.status === 'new' ? 'New' : d.status === 'in_progress' ? 'In Progress' : 'Closed',
            created_timestamp: d.created_timestamp,
            host_id: d.device.device_id,
            host_name: d.device.hostname || 'Unknown'
        }));

      } catch (fallbackError: any) {
         return { error: `Failed to fetch incidents (and fallback detections): ${e.message} / ${fallbackError.message}` };
      }
    }
  }

  async get_device_details(args: { identifier: string }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 600));
      const device = mockDevices.find(d => 
        d.device_id.toLowerCase() === args.identifier.toLowerCase() || 
        d.hostname.toLowerCase() === args.identifier.toLowerCase()
      );
      if (device) return device;
      return { error: `Device '${args.identifier}' not found.` };
    }

    try {
      // 1. Search for ID if identifier is a hostname
      let id = args.identifier;
      if (!id.startsWith('aid-') && !id.match(/^[0-9a-f]{32}$/i)) {
         const searchRes = await this.fetchAPI(`/devices/queries/devices/v1?filter=hostname:'${args.identifier}'`);
         if (searchRes.resources && searchRes.resources.length > 0) {
            id = searchRes.resources[0];
         } else {
            return { error: `Device with hostname '${args.identifier}' not found.` };
         }
      }

      // 2. Get Details
      const detailsRes = await this.fetchAPI(`/devices/entities/devices/v2`, 'POST', { ids: [id] });
      if (!detailsRes.resources || detailsRes.resources.length === 0) {
          return { error: `Device details not found for ID: ${id}` };
      }

      const d = detailsRes.resources[0];
      return {
          device_id: d.device_id,
          hostname: d.hostname,
          platform_name: d.platform_name,
          os_version: d.os_version,
          status: d.status,
          last_seen: d.last_seen,
          external_ip: d.external_ip
      };
    } catch (e: any) {
        return { error: e.message };
    }
  }

  async contain_host(args: { device_id: string }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 1500));
      const device = mockDevices.find(d => d.device_id === args.device_id);
      if (device) {
        device.status = 'contained';
        return { success: true, message: `Host ${args.device_id} has been successfully contained. Network access restricted.` };
      }
      return { error: `Device ${args.device_id} not found.` };
    }

    try {
        const res = await this.fetchAPI(`/devices/entities/devices-actions/v2?action_name=contain`, 'POST', { ids: [args.device_id] });
        if (res.errors && res.errors.length > 0) {
            return { error: res.errors[0].message };
        }
        return { success: true, message: `Command sent. Host ${args.device_id} is being contained.` };
    } catch (e: any) {
        return { error: e.message };
    }
  }

  async lift_containment(args: { device_id: string }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 1500));
      const device = mockDevices.find(d => d.device_id === args.device_id);
      if (device) {
        device.status = 'normal';
        return { success: true, message: `Containment lifted for host ${args.device_id}. Network access restored.` };
      }
      return { error: `Device ${args.device_id} not found.` };
    }

    try {
        const res = await this.fetchAPI(`/devices/entities/devices-actions/v2?action_name=lift_containment`, 'POST', { ids: [args.device_id] });
        if (res.errors && res.errors.length > 0) {
            return { error: res.errors[0].message };
        }
        return { success: true, message: `Command sent. Containment is being lifted for host ${args.device_id}.` };
    } catch (e: any) {
        return { error: e.message };
    }
  }

  async get_detections(args: { host_id?: string; limit?: number }) {
    if (this.config.useSimulation) {
      await new Promise(resolve => setTimeout(resolve, 800));
      const detections: Detection[] = [
        { detection_id: 'det-1', tactic: 'Execution', technique: 'Command and Scripting Interpreter', severity: 'High', timestamp: new Date().toISOString(), cmd_line: 'powershell.exe -enc ...' },
        { detection_id: 'det-2', tactic: 'Persistence', technique: 'Registry Run Keys', severity: 'Medium', timestamp: new Date().toISOString(), cmd_line: 'reg add HKLM\\...' }
      ];
      return detections;
    }

    try {
        let filter = "";
        if (args.host_id) {
            filter = `&filter=device.device_id:'${args.host_id}'`;
        }
        const queryRes = await this.fetchAPI(`/detects/queries/detects/v1?limit=${args.limit || 5}&sort=created_timestamp.desc${filter}`);
        const ids = queryRes.resources;

        if (!ids || ids.length === 0) return [];

        const detailsRes = await this.fetchAPI(`/detects/entities/summaries/GET/v1`, 'POST', { ids });

        return detailsRes.resources.map((d: any) => ({
            detection_id: d.detection_id,
            tactic: d.tactic || 'Unknown',
            technique: d.technique || 'Unknown',
            severity: d.max_severity >= 80 ? 'Critical' : d.max_severity >= 60 ? 'High' : 'Medium',
            timestamp: d.created_timestamp,
            cmd_line: d.behaviors?.[0]?.cmdline || 'N/A'
        }));
    } catch (e: any) {
        return { error: e.message };
    }
  }
}

