  }

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} mb-6 animate-fadeIn`}>
      <div className={`max-w-[85%] lg:max-w-[70%] flex gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center border ${
            isUser ? 'bg-indigo-600 border-indigo-400' : 
            isAlert ? 'bg-red-600 border-red-400 animate-pulse' : 'bg-falcon-800 border-falcon-accent'
        }`}>
          {isUser ? (
             <span className="text-white font-bold">U</span>
          ) : (
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
            </svg>
          )}
        </div>

        {/* Content */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          <div className="flex items-center gap-2 mb-1">
             <span className={`text-xs font-medium ${isAlert ? 'text-red-400 font-bold uppercase tracking-wider' : 'text-slate-400'}`}>
               {isUser ? 'You' : isAlert ? 'CRITICAL ALERT' : 'FalconAI'}
             </span>
             <span className="text-[10px] text-slate-600">
               {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
             </span>
          </div>

          <div className={`p-4 rounded-xl text-sm leading-relaxed shadow-lg backdrop-blur-sm ${
            isUser 
              ? 'bg-indigo-600 text-white rounded-tr-none' 
              : isAlert 
                ? 'bg-red-900/30 border border-red-500/50 text-red-100 rounded-tl-none' 
                : 'bg-falcon-800/80 border border-falcon-700 text-slate-200 rounded-tl-none'
          }`}>

            {message.toolCalls && <ToolExecutionCard tools={message.toolCalls} />}

            {message.isThinking && !message.content ? (
                 <span className="animate-pulse flex gap-1">
                    <span className="w-2 h-2 bg-slate-400 rounded-full"></span>
                    <span className="w-2 h-2 bg-slate-400 rounded-full animation-delay-200"></span>
                    <span className="w-2 h-2 bg-slate-400 rounded-full animation-delay-400"></span>
                 </span>
            ) : (
              <ReactMarkdown 
                className="markdown-content space-y-3"
                components={{
                  h3: ({node, ...props}) => <h3 className="text-lg font-bold text-white mt-2 mb-1" {...props} />,
                  ul: ({node, ...props}) => <ul className="list-disc list-inside space-y-1 ml-1" {...props} />,
                  li: ({node, ...props}) => <li className="text-slate-300" {...props} />,
                  code: ({node, ...props}) => <code className="bg-black/30 text-emerald-400 px-1 py-0.5 rounded font-mono text-xs" {...props} />,
                  pre: ({node, ...props}) => <pre className="bg-black/50 p-3 rounded-lg overflow-x-auto text-xs font-mono border border-slate-700 my-2" {...props} />,
                  table: ({node, ...props}) => <div className="overflow-x-auto my-3"><table className="min-w-full divide-y divide-slate-700 border border-slate-700 rounded-lg overflow-hidden" {...props} /></div>,
                  thead: ({node, ...props}) => <thead className="bg-slate-800" {...props} />,
                  th: ({node, ...props}) => <th className="px-3 py-2 text-left text-xs font-medium text-slate-400 uppercase tracking-wider" {...props} />,
                  td: ({node, ...props}) => <td className="px-3 py-2 whitespace-nowrap text-sm text-slate-300 border-t border-slate-700" {...props} />,
                  a: ({node, ...props}) => <a className="text-blue-400 hover:underline" {...props} />,
                  strong: ({node, ...props}) => <strong className="font-bold text-white" {...props} />
                }}
              >
                {message.content}
              </ReactMarkdown>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `**FalconAI Overwatch Online.** 

I am your autonomous security analyst. My systems are monitoring the Falcon stream.
- **Auto-Correlation**: Enabled
- **Real-time Defense**: Active
- **Data Stream**: Connected

I am standing by for commands.`,
  timestamp: new Date()
};

export default function App() {
  // State
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });

  // Configuration
  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  // Refs
  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  // Initialize Agent
  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- Real-time Overwatch Loop ---
  useEffect(() => {
      let interval: NodeJS.Timeout;

      if (monitoringEnabled && agentRef.current) {
          // Initial fetch for stats
          updateStats();

          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 30000); // Check every 30s
      }

      return () => clearInterval(interval);
  }, [monitoringEnabled, config]); // Re-run if config changes or monitoring toggled

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
      } catch (e) { console.error("Stats refresh failed", e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          // If we found a critical incident
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              // If it's different from the last one we saw
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;

                  // Inject Red Alert
                  const alertMsg: Message = {
                      id: crypto.randomUUID(),
                      role: 'model',
                      isAlert: true,
                      content: `### 🚨 CRITICAL THREAT DETECTED
**Incident**: ${latest.title} (${latest.incident_id})
**Host**: ${latest.host_name}

I have detected a new critical severity incident. Should I initiate containment protocol on ${latest.host_name}?`,
                      timestamp: new Date()
                  };
                  setMessages(prev => [...prev, alertMsg]);
                  // Play sound (optional, browser policy dependent)
              }
          }
      } catch (e) { /* ignore polling errors */ }
  };


  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isProcessing || !agentRef.current) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      await agentRef.current.processMessage(input, (updatedMsg) => {
        setMessages(prev => {
            const exists = prev.find(m => m.id === updatedMsg.id);
            if (exists) {
                return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
            }
            return [...prev, updatedMsg];
        });
      });
      // Refresh stats after interaction
      updateStats();
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex h-screen bg-falcon-900 text-slate-200 overflow-hidden font-sans">

      {/* Sidebar */}
      <aside className="hidden md:flex flex-col w-72 bg-slate-900 border-r border-falcon-800 shadow-2xl z-10">
        <div className="p-6 flex items-center gap-3 border-b border-falcon-800 bg-slate-950">
           <div className="w-8 h-8 rounded bg-falcon-accent flex items-center justify-center animate-pulse">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
              </svg>
           </div>
           <div>
               <h1 className="font-bold text-lg tracking-tight text-white leading-none">FALCON<span className="text-falcon-accent">AI</span></h1>
               <div className="text-[10px] text-slate-500 font-mono tracking-widest mt-1">WAR ROOM CONSOLE</div>
           </div>
        </div>

        {/* Live Metrics */}
        <div className="p-4 grid grid-cols-2 gap-3 bg-slate-900/50">
            <div className="col-span-2 bg-slate-800 p-3 rounded border border-slate-700">
                 <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-1">Threat Level</div>
                 <div className={`text-xl font-bold ${stats.criticalCount > 0 ? 'text-red-500 animate-pulse' : 'text-emerald-500'}`}>
                     {stats.criticalCount > 0 ? 'SEVERE' : 'NORMAL'}
                 </div>
            </div>
            <div className="bg-slate-800 p-3 rounded border border-slate-700">
                <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-1">Critical</div>
                <div className="text-2xl font-mono text-white">{stats.criticalCount}</div>
            </div>
            <div className="bg-slate-800 p-3 rounded border border-slate-700">
                <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-1">Active</div>
                <div className="text-2xl font-mono text-white">{stats.openIncidents}</div>
            </div>
            <div className="bg-slate-800 p-3 rounded border border-slate-700 col-span-2 flex justify-between items-center">
                <div>
                    <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider">Contained Hosts</div>
                    <div className="text-2xl font-mono text-white">{stats.containedHosts}</div>
                </div>
                <svg className="w-8 h-8 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
        </div>

        <div className="flex-1 p-4 space-y-2 overflow-y-auto">
            <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">One-Click Actions</div>
            <button className="w-full text-left px-3 py-2 text-xs font-mono text-slate-300 hover:bg-falcon-800 border border-transparent hover:border-falcon-700 rounded transition-all"
                onClick={() => setInput("Generate a threat briefing for all critical incidents.")}
            >
                > BRIEFING_GEN
            </button>
             <button className="w-full text-left px-3 py-2 text-xs font-mono text-slate-300 hover:bg-falcon-800 border border-transparent hover:border-falcon-700 rounded transition-all"
                onClick={() => setInput("Identify all hosts with detections in the last hour.")}
             >
                > HOST_TRIAGE
            </button>
        </div>

        <div className="p-4 border-t border-falcon-800 bg-slate-950">
            <div className="flex items-center justify-between mb-4">
                 <span className="text-xs font-bold text-slate-400">OVERWATCH MODE</span>
                 <button 
                    onClick={() => setMonitoringEnabled(!monitoringEnabled)}
                    className={`w-10 h-5 rounded-full relative transition-colors ${monitoringEnabled ? 'bg-emerald-500' : 'bg-slate-700'}`}
                 >
                     <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${monitoringEnabled ? 'left-6' : 'left-1'}`}></div>
                 </button>
            </div>

            <button 
                onClick={() => setIsSettingsOpen(true)}
                className="w-full flex items-center justify-center gap-2 px-3 py-2 text-sm font-medium text-slate-400 bg-falcon-800 hover:bg-falcon-700 hover:text-white rounded transition-colors"
            >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
                API Settings
            </button>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative bg-slate-950/50">
        <header className="md:hidden flex items-center justify-between p-4 border-b border-falcon-800 bg-falcon-900">
             <h1 className="font-bold text-white">Falcon<span className="text-falcon-accent">AI</span></h1>
             <button onClick={() => setIsSettingsOpen(true)} className="text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
        </header>

        {monitoringEnabled && (
            <div className="hidden md:block absolute top-4 right-8 z-20">
                <div className="flex items-center gap-2 px-3 py-1.5 bg-emerald-900/40 border border-emerald-500/30 rounded-full backdrop-blur-sm">
                    <span className="relative flex h-2 w-2">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                    </span>
                    <span className="text-[10px] font-bold text-emerald-400 tracking-wider">LIVE STREAM ACTIVE</span>
                </div>
            </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-4">
           {messages.map((msg) => (
             <ChatMessage key={msg.id} message={msg} />
           ))}
           <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 md:p-6 bg-falcon-900 border-t border-falcon-800">
           <form onSubmit={handleSendMessage} className="max-w-4xl mx-auto relative">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                disabled={isProcessing}
                placeholder={isProcessing ? "Processing..." : monitoringEnabled ? "Command Line Active... (Type 'help' for options)" : "Enter command or query..."}
                className="w-full bg-falcon-800/50 border border-falcon-700 text-white rounded-xl py-4 pl-5 pr-12 focus:outline-none focus:border-falcon-tech focus:ring-1 focus:ring-falcon-tech shadow-lg transition-all disabled:opacity-50 font-mono text-sm"
              />
              <button 
                type="submit"
                disabled={!input.trim() || isProcessing}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-falcon-tech text-white rounded-lg hover:bg-blue-600 disabled:bg-slate-700 disabled:cursor-not-allowed transition-colors"
              >
                {isProcessing ? (
                     <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                ) : (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                )}
              </button>
           </form>
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        config={config} 
        onSave={(newConfig) => {
            setConfig(newConfig);
            // Trigger an immediate check if monitoring is on
            if(monitoringEnabled) updateStats();
        }} 
      />
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `**FalconAI Overwatch Online.** 

I am your autonomous security analyst. My systems are monitoring the Falcon stream.
- **Auto-Correlation**: Enabled
- **Real-time Defense**: Active
- **Data Stream**: Connected

I am standing by for commands.`,
  timestamp: new Date()
};

export default function App() {
  // State
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });

  // Configuration
  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  // Refs
  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  // Initialize Agent
  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- Real-time Overwatch Loop ---
  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;

      if (monitoringEnabled && agentRef.current) {
          // Initial fetch for stats
          updateStats();

          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 30000); // Check every 30s
      }

      return () => {
        if (interval) clearInterval(interval);
      };
  }, [monitoringEnabled, config]); // Re-run if config changes or monitoring toggled

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
      } catch (e) { console.error("Stats refresh failed", e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          // If we found a critical incident
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              // If it's different from the last one we saw
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;

                  // Inject Red Alert
                  const alertMsg: Message = {
                      id: crypto.randomUUID(),
                      role: 'model',
                      isAlert: true,
                      content: `### 🚨 CRITICAL THREAT DETECTED
**Incident**: ${latest.title} (${latest.incident_id})
**Host**: ${latest.host_name}

I have detected a new critical severity incident. Should I initiate containment protocol on ${latest.host_name}?`,
                      timestamp: new Date()
                  };
                  setMessages(prev => [...prev, alertMsg]);
                  // Play sound (optional, browser policy dependent)
              }
          }
      } catch (e) { /* ignore polling errors */ }
  };


  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isProcessing || !agentRef.current) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      await agentRef.current.processMessage(input, (updatedMsg) => {
        setMessages(prev => {
            const exists = prev.find(m => m.id === updatedMsg.id);
            if (exists) {
                return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
            }
            return [...prev, updatedMsg];
        });
      });
      // Refresh stats after interaction
      updateStats();
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

