import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, ToolCallDetails } from '../types';

interface ChatMessageProps {
  message: Message;
}

const ToolExecutionCard: React.FC<{ tools: ToolCallDetails[] }> = ({ tools }) => (
  <div className="mb-3 group">
    <div className="flex flex-col gap-1">
      {tools.map((t, idx) => (
        <div key={idx} className="flex items-center gap-2 text-[10px] font-mono text-nexus-accent/70 bg-nexus-accent/5 px-2 py-1 rounded border border-nexus-accent/10 w-fit">
          <span className="w-1.5 h-1.5 bg-nexus-accent rounded-full animate-pulse"></span>
          <span className="opacity-75">EXECUTE_SUBROUTINE ::</span>
          <span className="font-bold">{t.functionName}</span>
          <span className="text-slate-500 truncate max-w-[200px]">{JSON.stringify(t.args)}</span>
        </div>
      ))}
    </div>
  </div>
);

export const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const isSystem = message.role === 'system';
  const isAlert = message.isAlert;

  if (isSystem) {
    return (
      <div className="flex justify-center my-6 animate-fadeIn">
        <div className="bg-red-500/10 border border-red-500/30 text-red-400 px-4 py-1.5 rounded-full text-xs font-mono tracking-wide">
          SYSTEM_ERROR :: {message.content}
        </div>
      </div>
    );
  }

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} mb-8 animate-fadeIn group`}>
      <div className={`max-w-[90%] lg:max-w-[75%] flex gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-8 h-8 mt-1 rounded md:rounded-lg flex items-center justify-center border shadow-[0_0_15px_rgba(0,0,0,0.3)] transition-all duration-300 ${
            isUser ? 'bg-nexus-accent/20 border-nexus-accent/50 shadow-nexus-accent/20' : 
            isAlert ? 'bg-nexus-critical/20 border-nexus-critical/50 shadow-nexus-critical/20 animate-pulse-slow' : 'bg-nexus-800 border-nexus-border'
        }`}>
          {isUser ? (
             <svg className="w-4 h-4 text-nexus-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
          ) : (
            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          )}
        </div>

        {/* Content */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} flex-1 min-w-0`}>
          <div className="flex items-center gap-3 mb-1.5 pl-1 opacity-60 text-[10px] font-mono tracking-widest uppercase">
             <span className={`${isAlert ? 'text-nexus-critical font-bold' : isUser ? 'text-nexus-accent' : 'text-slate-400'}`}>
               {isUser ? 'OPERATOR' : isAlert ? 'CRITICAL_INTERRUPT' : 'NEXUS_CORE'}
             </span>
             <span className="text-slate-600">
               {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
             </span>
          </div>

          <div className={`p-5 rounded-lg text-sm leading-relaxed backdrop-blur-md shadow-2xl border transition-all duration-300 ${
            isUser 
              ? 'bg-nexus-accent/10 border-nexus-accent/30 text-slate-100 rounded-tr-none' 
              : isAlert 
                ? 'bg-nexus-critical/5 border-nexus-critical/40 text-red-50 rounded-tl-none shadow-[0_0_30px_-5px_rgba(244,63,94,0.15)]' 
                : 'glass-panel text-slate-200 rounded-tl-none hover:border-white/20'
          }`}>

            {message.toolCalls && <ToolExecutionCard tools={message.toolCalls} />}

            {message.isThinking && !message.content ? (
                 <div className="flex items-center gap-2 py-1">
                    <span className="w-1.5 h-1.5 bg-nexus-accent rounded-full animate-bounce"></span>
                    <span className="w-1.5 h-1.5 bg-nexus-accent rounded-full animate-bounce delay-100"></span>
                    <span className="w-1.5 h-1.5 bg-nexus-accent rounded-full animate-bounce delay-200"></span>
                    <span className="text-xs font-mono text-nexus-accent/50 ml-2">PROCESSING_LOGIC_CHAIN</span>
                 </div>
            ) : (
              <ReactMarkdown 
                className="markdown-content space-y-3"
                components={{
                  h3: ({node, ...props}) => <h3 className="text-base font-display font-bold text-white mt-4 mb-2 tracking-wide flex items-center gap-2" {...props} />,
                  ul: ({node, ...props}) => <ul className="space-y-1.5 my-2" {...props} />,
                  li: ({node, ...props}) => <li className="flex items-start gap-2 text-slate-300 pl-1" {...props}><span className="mt-1.5 w-1 h-1 bg-nexus-accent rounded-full flex-shrink-0" /> <span className="flex-1">{props.children}</span></li>,
                  code: ({node, ...props}) => <code className="bg-black/40 text-nexus-accent px-1.5 py-0.5 rounded font-mono text-xs border border-nexus-accent/20" {...props} />,
                  pre: ({node, ...props}) => <pre className="bg-black/60 p-4 rounded-lg overflow-x-auto text-xs font-mono border border-white/10 my-3 shadow-inner" {...props} />,
                  table: ({node, ...props}) => <div className="overflow-x-auto my-4 rounded-lg border border-white/10"><table className="min-w-full divide-y divide-white/10 bg-black/20" {...props} /></div>,
                  thead: ({node, ...props}) => <thead className="bg-white/5" {...props} />,
                  th: ({node, ...props}) => <th className="px-4 py-3 text-left text-xs font-bold text-slate-300 uppercase tracking-wider font-display" {...props} />,
                  td: ({node, ...props}) => <td className="px-4 py-3 whitespace-nowrap text-sm text-slate-400 border-t border-white/5 font-mono" {...props} />,
                  a: ({node, ...props}) => <a className="text-nexus-accent hover:text-white transition-colors underline decoration-nexus-accent/50 underline-offset-4" {...props} />,
                  strong: ({node, ...props}) => <strong className="font-bold text-white" {...props} />,
                  p: ({node, ...props}) => <p className="leading-relaxed" {...props} />
                }}
              >
                {message.content}
              </ReactMarkdown>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### NEXUS_CORE // ONLINE
**System Status**: Nominal
**Connection**: Secure
**AI Model**: Gemini 2.5 (High-Reasoning)

I am **Falcon Nexus**. I am connected to your CrowdStrike environment.
My primary function is **autonomous threat correlation**.

*   I do not just list alerts; I investigate the *context* around them.
*   I can execute **Containment Protocols** on your command.

Awaiting directive.`,
  timestamp: new Date()
};

export default function App() {
  // State
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });

  // Configuration
  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  // Refs
  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  // Initialize Agent
  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- Autonomous Sentinel Loop ---
  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;

      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 30000); 
      }

      return () => {
        if (interval) clearInterval(interval);
      };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
      } catch (e) { console.error("Stats refresh failed", e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;

                  const alertMsg: Message = {
                      id: crypto.randomUUID(),
                      role: 'model',
                      isAlert: true,
                      content: `### 🚨 THREAT INTERCEPT
**Severity**: CRITICAL
**Incident**: ${latest.title}
**Target**: ${latest.host_name} (${latest.host_id})

Falcon Nexus has correlated this incident with high-risk behavior.
**Recommendation**: Immediate Network Containment.

Execute protocol?`,
                      timestamp: new Date()
                  };
                  setMessages(prev => [...prev, alertMsg]);
              }
          }
      } catch (e) { /* ignore polling errors */ }
  };


  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isProcessing || !agentRef.current) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      await agentRef.current.processMessage(input, (updatedMsg) => {
        setMessages(prev => {
            const exists = prev.find(m => m.id === updatedMsg.id);
            if (exists) {
                return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
            }
            return [...prev, updatedMsg];
        });
      });
      updateStats();
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex h-screen bg-nexus-950 text-slate-200 overflow-hidden font-sans selection:bg-nexus-accent/30 selection:text-white">

      {/* --- SIDEBAR --- */}
      <aside className="hidden md:flex flex-col w-80 glass-panel border-r border-white/5 z-20">

        {/* Brand Header */}
        <div className="p-6 border-b border-white/5 bg-gradient-to-r from-nexus-900/50 to-transparent">
           <div className="flex items-center gap-3">
             <div className="relative">
                <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-nexus-accent to-blue-700 flex items-center justify-center shadow-lg shadow-nexus-accent/20">
                    <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
