                    </svg>
                </div>
                {monitoringEnabled && <div className="absolute -top-1 -right-1 w-3 h-3 bg-nexus-success rounded-full border-2 border-nexus-950 animate-pulse"></div>}
             </div>
             <div>
                 <h1 className="font-display font-bold text-lg tracking-wide text-white leading-none">FALCON<span className="text-nexus-accent">NEXUS</span></h1>
                 <div className="text-[10px] text-slate-500 font-mono tracking-widest mt-1.5 uppercase">Unified Defense Grid</div>
             </div>
           </div>
        </div>

        {/* Global Stats Matrix */}
        <div className="p-6 space-y-4">
            <div className="flex justify-between items-center mb-2">
                <span className="text-[10px] uppercase font-bold text-slate-500 tracking-widest">Environment Status</span>
                <div className={`w-2 h-2 rounded-full ${stats.criticalCount > 0 ? 'bg-nexus-critical animate-ping' : 'bg-nexus-success'}`}></div>
            </div>

            <div className="grid grid-cols-2 gap-3">
                <div className="glass-panel p-4 rounded-lg border-l-2 border-l-nexus-critical bg-gradient-to-br from-nexus-critical/10 to-transparent">
