                    <div className="text-2xl font-display font-bold text-white">{stats.criticalCount}</div>
                </div>
                <div className="glass-panel p-4 rounded-lg border-l-2 border-l-nexus-accent bg-gradient-to-br from-nexus-accent/10 to-transparent">
