                    className="w-full bg-nexus-900/90 border border-white/10 text-white rounded-xl py-5 pl-12 pr-14 focus:outline-none focus:border-nexus-accent/50 focus:ring-1 focus:ring-nexus-accent/50 shadow-2xl transition-all disabled:opacity-50 font-mono text-sm placeholder:text-slate-600"
                  />
                  <button 
                    type="submit"
                    disabled={!input.trim() || isProcessing}
                    className="absolute right-3 p-2 bg-nexus-accent/10 text-nexus-accent rounded-lg hover:bg-nexus-accent hover:text-white disabled:bg-transparent disabled:text-slate-700 disabled:cursor-not-allowed transition-all"
                  >
                    {isProcessing ? (
                        <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    ) : (
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                    )}
                  </button>
              </form>
              <div className="absolute -bottom-6 right-0 text-[10px] text-slate-600 font-mono">
                  POWERED BY GEMINI 2.5 // SECURE CHANNEL
              </div>
           </div>
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        config={config} 
        onSave={(newConfig) => {
            setConfig(newConfig);
            if(monitoringEnabled) updateStats();
        }} 
      />
    </div>
  );
}

