import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### FALCON COMMAND // ONLINE
**System Status**: NOMINAL
**Agent**: ACTIVE

I am standing by to correlate threats and execute defense protocols.
**Directives**:
*   Monitor Incident Stream
*   Correlate Host Telemetry
*   Authorize Containment

Awaiting input.`,
  timestamp: new Date()
};

export default function App() {
  // State
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });

  // Configuration
  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  // Refs
  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  // Initialize Agent
  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- Autonomous Sentinel Loop ---
  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;

      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 30000); 
      }

      return () => {
        if (interval) clearInterval(interval);
      };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
      } catch (e) { console.error("Stats refresh failed", e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;

                  const alertMsg: Message = {
                      id: crypto.randomUUID(),
                      role: 'model',
                      isAlert: true,
                      content: `### 🚨 CRITICAL THREAT DETECTED
**Incident ID**: ${latest.incident_id}
**Target Host**: ${latest.host_name}
**Threat Level**: CRITICAL

Automated analysis indicates active compromise.
**Protocol**: IMMEDIATE CONTAINMENT RECOMMENDED.

**AUTHORIZATION REQUIRED**:
Type **"AUTHORIZE"** or **"YES"** to execute network containment on ${latest.host_name}.`,
                      timestamp: new Date()
                  };
                  setMessages(prev => [...prev, alertMsg]);
              }
          }
      } catch (e) { /* ignore polling errors */ }
  };


  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isProcessing || !agentRef.current) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      await agentRef.current.processMessage(input, (updatedMsg) => {
        setMessages(prev => {
            const exists = prev.find(m => m.id === updatedMsg.id);
            if (exists) {
                return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
            }
            return [...prev, updatedMsg];
        });
      });
      updateStats();
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex h-screen bg-cs-base text-cs-text overflow-hidden font-sans selection:bg-cs-red selection:text-white bg-grid">

      {/* --- SIDEBAR --- */}
      <aside className="hidden md:flex flex-col w-80 bg-black border-r border-cs-border z-20 shadow-2xl">

        {/* Brand Header */}
        <div className="p-6 border-b border-cs-border bg-cs-surface">
           <div className="flex items-center gap-3">
             <div className="relative group">
                {/* CrowdStrike Logo Icon */}
                <div className="w-10 h-10 flex items-center justify-center text-cs-red transition-transform group-hover:scale-110">
                    <svg className="w-8 h-8" viewBox="0 0 24 24" fill="currentColor">
                         <path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zm4.24 16L12 15.45 7.77 18l1.12-4.81-3.73-3.23 4.92-.42L12 5l1.92 4.53 4.92.42-3.73 3.23L16.23 18z"/>
                    </svg>
                </div>
                {monitoringEnabled && <div className="absolute top-0 right-0 w-2 h-2 bg-cs-red rounded-full animate-pulse shadow-[0_0_10px_#FC0000]"></div>}
             </div>
             <div>
                 <h1 className="font-display font-bold text-xl tracking-tight text-white leading-none">FALCON</h1>
                 <div className="text-[10px] text-cs-red font-bold tracking-[0.2em] mt-1 uppercase">Command</div>
             </div>
           </div>
        </div>

        {/* Global Stats Matrix */}
        <div className="p-6 space-y-4 bg-black">
            <div className="flex justify-between items-center mb-2 border-b border-cs-border pb-2">
                <span className="text-[10px] uppercase font-bold text-cs-dim tracking-widest">Global Status</span>
                <div className={`w-2 h-2 ${stats.criticalCount > 0 ? 'bg-cs-red animate-flash' : 'bg-emerald-500'}`}></div>
            </div>

            <div className="grid grid-cols-2 gap-3">
                <div className="bg-cs-surface p-4 border border-cs-border border-l-2 border-l-cs-red">
                    <div className="text-[10px] text-cs-dim font-mono mb-1 uppercase">Critical</div>
                    <div className="text-3xl font-display font-bold text-white">{stats.criticalCount}</div>
                </div>
                <div className="bg-cs-surface p-4 border border-cs-border">
                    <div className="text-[10px] text-cs-dim font-mono mb-1 uppercase">Active</div>
                    <div className="text-3xl font-display font-bold text-white">{stats.openIncidents}</div>
                </div>
            </div>

            <div className="bg-cs-surface p-4 border border-cs-border flex items-center justify-between">
                <div>
                     <div className="text-[10px] text-cs-dim font-mono mb-1 uppercase">Contained</div>
                     <div className="text-2xl font-display font-bold text-white">{stats.containedHosts}</div>
                </div>
                <svg className="w-8 h-8 text-cs-border" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
        </div>

        {/* Quick Actions */}
        <div className="flex-1 px-6 space-y-2 overflow-y-auto bg-black border-t border-cs-border/30">
