import React, { useState } from 'react';
import { AppConfig } from '../types';
import { CrowdStrikeService } from '../services/crowdstrikeService';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: AppConfig;
  onSave: (config: AppConfig) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, config, onSave }) => {
  const [formData, setFormData] = useState<AppConfig>(config);
  const [isValidating, setIsValidating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSave = async () => {
      setError(null);
      setIsValidating(true);

      const tester = new CrowdStrikeService(formData);
      try {
          await tester.testConnection();
          onSave(formData);
          onClose();
      } catch (e: any) {
          setError(e.message);
      } finally {
          setIsValidating(false);
      }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fadeIn">
      <div className="bg-cs-bg border border-cs-border w-full max-w-2xl shadow-[0_0_50px_rgba(0,0,0,0.8)] flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="p-6 border-b border-cs-border bg-cs-surface flex items-center justify-between">
            <div>
                <h2 className="text-lg font-bold text-white uppercase tracking-wider flex items-center gap-2">
                    <span className="w-1 h-5 bg-cs-red block"></span>
                    API Configuration
                </h2>
            </div>
            <div className="text-[10px] font-mono text-cs-dim">SECURE_GATEWAY_V1</div>
        </div>

        {/* Content */}
        <div className="p-8 overflow-y-auto custom-scrollbar space-y-8 flex-1">

              <div className="space-y-6">

                 {/* Scopes Instruction */}
                 <div className="bg-black border border-cs-border p-5">
                    <h3 className="text-xs font-bold text-cs-red mb-4 uppercase tracking-widest flex items-center gap-2">
                        REQUIRED PERMISSIONS
                    </h3>

                    <div className="grid grid-cols-2 gap-3">
                        {['Alerts: Read', 'Detections: Read', 'Hosts: Read', 'Hosts: Write'].map((scope) => (
                             <div key={scope} className="flex items-center justify-between text-xs text-cs-dim bg-cs-surface p-2 border border-cs-border/50">
                                <span className="font-mono">{scope.split(':')[0]}</span>
                                <span className={`text-[10px] font-bold px-1.5 py-0.5 ${scope.includes('Write') ? 'text-white bg-cs-red' : 'text-cs-bg bg-white'}`}>
                                    {scope.split(':')[1].trim().toUpperCase()}
                                </span>
                             </div>
                        ))}
                    </div>
                 </div>

                 {/* Inputs */}
                 <div className="grid gap-6">
                    <div className="group">
                        <label className="block text-[10px] font-bold text-cs-dim uppercase tracking-widest mb-2 group-focus-within:text-white transition-colors">Client ID</label>
                        <input 
                        type="text" 
                        value={formData.clientId}
