        {/* Sentinel Toggle & Config */}
        <div className="p-6 border-t border-white/10 bg-black/40">
            {/* Activate Sentinel Button - High Contrast */}
            <div className="relative group mb-4">
                {monitoringEnabled && <div className="absolute inset-0 bg-cs-red/20 blur-md animate-pulse"></div>}
                <button 
                    onClick={() => setMonitoringEnabled(!monitoringEnabled)}
                    className={`relative w-full flex items-center justify-center gap-3 py-4 px-4 text-xs font-bold transition-all uppercase tracking-widest border-2 ${
                        monitoringEnabled 
                        ? 'bg-cs-red border-cs-red text-white shadow-[0_0_20px_#FC0000]' 
                        : 'bg-transparent border-cs-red text-cs-red hover:bg-cs-red hover:text-white'
                    }`}
                >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                    {monitoringEnabled ? 'SENTINEL ACTIVE' : 'ACTIVATE SENTINEL'}
