        <div className="p-4 md:p-8 pt-0">
           <div className="max-w-5xl mx-auto relative group">
              <div className="absolute -inset-1 bg-cs-red opacity-10 group-hover:opacity-30 blur-lg transition duration-1000"></div>
              <form onSubmit={handleSendMessage} className="relative flex items-center">
                  <div className="absolute left-4 text-cs-dim">
                      <span className="font-mono text-cs-red mr-2">$</span>
                  </div>
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    disabled={isProcessing}
                    placeholder={isProcessing ? "PROCESSING STREAM..." : monitoringEnabled ? "SENTINEL ACTIVE // AWAITING COMMAND..." : "ENTER COMMAND..."}
                    className="w-full bg-black border border-cs-border text-white rounded-none py-5 pl-10 pr-14 focus:outline-none focus:border-cs-red focus:ring-1 focus:ring-cs-red transition-all disabled:opacity-50 font-mono text-sm placeholder:text-cs-dim tracking-wide"
                  />
                  <button 
                    type="submit"
                    disabled={!input.trim() || isProcessing}
                    className="absolute right-3 p-2 text-cs-red hover:text-white disabled:text-cs-border disabled:cursor-not-allowed transition-all"
                  >
                    {isProcessing ? (
                        <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    ) : (
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                    )}
                  </button>
              </form>
              <div className="absolute -bottom-6 right-0 text-[10px] text-cs-dim font-mono flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-cs-red rounded-full"></span>
                  SECURE CONNECTION // GEMINI 2.5
              </div>
           </div>
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        config={config} 
        onSave={(newConfig) => {
            setConfig(newConfig);
            if(monitoringEnabled) updateStats();
        }} 
      />
    </div>
  );
}

