    try {
      await agentRef.current.processMessage(input, (updatedMsg) => {
        setMessages(prev => {
            const exists = prev.find(m => m.id === updatedMsg.id);
            if (exists) {
                return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
            }
            return [...prev, updatedMsg];
        });
      });
      updateStats();
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex h-screen bg-black text-white overflow-hidden font-sans selection:bg-cs-red selection:text-white bg-grid">

