import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, ToolCallDetails } from '../types';

interface ChatMessageProps {
  message: Message;
}

const ToolExecutionCard: React.FC<{ tools: ToolCallDetails[] }> = ({ tools }) => (
  <div className="mb-4 group">
    <div className="flex flex-col gap-2">
      {tools.map((t, idx) => (
        <div key={idx} className="flex items-center gap-3 text-[11px] font-mono text-white bg-cs-surface border border-cs-border px-3 py-2 w-fit rounded-sm shadow-sm hover:border-cs-red/40 transition-colors">
          <span className="w-2 h-2 bg-cs-red rounded-none animate-pulse"></span>
          <span className="opacity-75 uppercase tracking-wider text-cs-dim">EXECUTE ::</span>
          <span className="font-bold text-white">{t.functionName}</span>
          <span className="text-gray-500 truncate max-w-[250px]">{JSON.stringify(t.args)}</span>
        </div>
      ))}
    </div>
  </div>
);

export const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const isSystem = message.role === 'system';
  const isAlert = message.isAlert;

  if (isSystem) {
    return (
      <div className="flex justify-center my-6 animate-fadeIn">
        <div className="bg-red-950/30 border border-cs-red text-red-400 px-6 py-2 text-xs font-mono tracking-wide uppercase shadow-[0_0_15px_-5px_rgba(252,0,0,0.3)]">
          SYSTEM_ERROR :: {message.content}
        </div>
      </div>
    );
  }

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} mb-8 animate-fadeIn group`}>
      <div className={`max-w-[90%] lg:max-w-[80%] flex gap-5 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center border transition-all duration-300 shadow-md rounded-sm ${
            isUser ? 'bg-cs-surface border-cs-border' : 
            isAlert ? 'bg-cs-red border-cs-red shadow-[0_0_15px_rgba(252,0,0,0.4)] animate-pulse-fast' : 'bg-black border-cs-border'
        }`}>
          {isUser ? (
             <svg className="w-5 h-5 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
          ) : (
            <svg className="w-6 h-6 text-white" viewBox="0 0 24 24" fill="currentColor">
               <path d="M12 2L2 7l10 5 10-5-10-5zm0 9l2-1-2-1-2 1 2 1zm0 2l-5-2.5 5-2.5 5 2.5L12 13zM2 17l10 5 10-5M2 12l10 5 10-5" />
            </svg>
          )}
        </div>

        {/* Content */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} flex-1 min-w-0`}>
          <div className="flex items-center gap-3 mb-2 pl-1 text-[11px] font-mono tracking-widest uppercase">
             <span className={`${isAlert ? 'text-cs-red font-bold animate-pulse' : isUser ? 'text-white' : 'text-cs-dim'}`}>
               {isUser ? 'OPERATOR' : isAlert ? 'CRITICAL_THREAT' : 'FALCON_COMMAND'}
             </span>
             <span className="text-gray-600">
               {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
             </span>
          </div>

          <div className={`p-6 text-sm leading-relaxed border shadow-lg transition-all duration-300 rounded-sm ${
            isUser 
              ? 'bg-cs-surface border-cs-border text-gray-100' 
              : isAlert 
                ? 'bg-red-950/20 border-cs-red text-white shadow-[0_0_20px_-5px_rgba(252,0,0,0.1)]' 
                : 'bg-black border-cs-border text-gray-200'
          }`}>

            {message.toolCalls && <ToolExecutionCard tools={message.toolCalls} />}

            {message.isThinking && !message.content ? (
