                  table: ({node, ...props}) => <div className="overflow-x-auto my-4 border border-cs-border"><table className="min-w-full divide-y divide-cs-border bg-[#050505]" {...props} /></div>,
                  thead: ({node, ...props}) => <thead className="bg-cs-surface" {...props} />,
                  th: ({node, ...props}) => <th className="px-4 py-3 text-left text-[10px] font-bold text-white uppercase tracking-widest" {...props} />,
                  td: ({node, ...props}) => <td className="px-4 py-3 whitespace-nowrap text-xs text-gray-400 border-t border-cs-border font-mono" {...props} />,
                  a: ({node, ...props}) => <a className="text-white hover:text-cs-red transition-colors underline decoration-cs-red underline-offset-4" {...props} />,
                  strong: ({node, ...props}) => <strong className="font-bold text-white" {...props} />,
