            <div className="bg-zinc-900/30 p-4 border border-white/20 flex items-center justify-between hover:border-white transition-all shadow-lg cursor-default">
                <div>
                     <div className="text-[11px] text-gray-300 font-bold font-mono mb-1 uppercase tracking-wide">Contained Hosts</div>
                     <div className="text-2xl font-display font-bold text-white">{stats.containedHosts}</div>
