import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats, Incident } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### FALCON COMMAND // ONLINE
**System Status**: NOMINAL
**Agent**: ACTIVE

I am standing by to correlate threats and execute defense protocols.
**Directives**:
*   Monitor Incident Stream
*   Correlate Host Telemetry
*   Authorize Containment

Awaiting input.`,
  timestamp: new Date()
};

export default function App() {
  // State
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [criticalAlert, setCriticalAlert] = useState<Incident | null>(null);

  // Configuration
  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  // Refs
  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  // Initialize Agent
  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- Autonomous Sentinel Loop ---
  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;

      if (monitoringEnabled && agentRef.current) {
          updateStats();
          // POLL EVERY 15 SECONDS for "Real-time" feel
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 15000); 
      }

      return () => {
        if (interval) clearInterval(interval);
      };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
      } catch (e) { console.error("Stats refresh failed", e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              // Trigger on ANY open critical that we haven't just dismissed/seen in this loop
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;

                  // Trigger Full Screen Alert
                  setCriticalAlert(latest);

                  const alertMsg: Message = {
                      id: crypto.randomUUID(),
                      role: 'model',
                      isAlert: true,
                      content: `### 🚨 CRITICAL THREAT DETECTED
**Incident ID**: ${latest.incident_id}
**Target Host**: ${latest.host_name} (ID: ${latest.host_id})
**Threat Level**: CRITICAL

Automated analysis indicates active compromise.
**Protocol**: IMMEDIATE CONTAINMENT RECOMMENDED.

**AUTHORIZATION REQUIRED**:
Type **"AUTHORIZE"** or **"YES"** to execute network containment on ${latest.host_name}.`,
                      timestamp: new Date()
                  };
                  setMessages(prev => [...prev, alertMsg]);
              }
          }
      } catch (e) { /* ignore polling errors */ }
  };

  const processUserMessage = async (msgText: string) => {
      if (!msgText.trim() || isProcessing || !agentRef.current) return;

      const userMsg: Message = {
        id: crypto.randomUUID(),
        role: 'user',
        content: msgText,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, userMsg]);
      setInput('');
      setIsProcessing(true);

      try {
        await agentRef.current.processMessage(msgText, (updatedMsg) => {
          setMessages(prev => {
              const exists = prev.find(m => m.id === updatedMsg.id);
              if (exists) {
                  return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
              }
              return [...prev, updatedMsg];
          });
        });
        updateStats();
      } catch (err) {
        console.error(err);
      } finally {
        setIsProcessing(false);
      }
  }

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    processUserMessage(input);
  };

  return (
    <div className="flex h-screen bg-black text-white overflow-hidden font-sans selection:bg-cs-red selection:text-white bg-grid relative">

      {/* --- CRITICAL ALERT OVERLAY --- */}
      {criticalAlert && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-4 animate-fadeIn">
            <div className="bg-black border-[3px] border-cs-red shadow-[0_0_100px_rgba(255,0,0,0.6)] max-w-3xl w-full p-10 relative overflow-hidden group">
               {/* Scanlines Effect */}
               <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-0 pointer-events-none bg-[length:100%_4px,3px_100%]"></div>
               <div className="absolute top-0 left-0 w-full h-1 bg-cs-red animate-pulse"></div>

               <div className="relative z-10 text-center space-y-8">
                  <div className="inline-flex items-center justify-center w-28 h-28 rounded-full bg-red-950/40 border-[4px] border-cs-red text-cs-red mb-4 shadow-[0_0_40px_rgba(255,0,0,0.5)] animate-pulse">
                     <svg className="w-14 h-14" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>

                  <div>
                    <h2 className="text-6xl font-display font-bold text-white tracking-tighter uppercase mb-3 drop-shadow-[0_4px_4px_rgba(0,0,0,0.8)]">CRITICAL THREAT</h2>
                    <p className="text-cs-red font-mono text-2xl tracking-[0.3em] uppercase font-bold animate-pulse">IMMEDIATE ATTENTION REQUIRED</p>
                  </div>

                  <div className="bg-zinc-900 border-2 border-cs-red/50 p-6 text-left space-y-4 shadow-lg">
                     <div className="flex justify-between border-b border-gray-600 pb-3 items-end">
                        <span className="text-gray-300 text-sm uppercase tracking-wider font-bold">Target Host</span>
                        <span className="text-white font-mono font-bold text-3xl tracking-tight">{criticalAlert.host_name}</span>
                     </div>
                     <div className="flex justify-between border-b border-gray-600 pb-3 items-end">
                         <span className="text-gray-300 text-sm uppercase tracking-wider font-bold">Incident ID</span>
                         <span className="text-cs-red font-mono font-bold text-xl">{criticalAlert.incident_id}</span>
                     </div>
                     <div className="flex justify-between items-end">
                         <span className="text-gray-300 text-sm uppercase tracking-wider font-bold">Detection Time</span>
                         <span className="text-white font-mono text-lg font-bold">{new Date(criticalAlert.created_timestamp).toLocaleTimeString()}</span>
                     </div>
                  </div>

                  <button 
                    onClick={() => {
                        // AUTOMATED WORKFLOW TRIGGER
                        const command = `AUTHORIZE CONTAINMENT on host ${criticalAlert.host_name} (ID: ${criticalAlert.host_id}) for incident ${criticalAlert.incident_id}`;
                        setCriticalAlert(null);
                        processUserMessage(command);
                    }}
                    className="w-full bg-cs-red hover:bg-white hover:text-cs-red text-white font-bold py-5 px-8 uppercase tracking-[0.25em] transition-all hover:shadow-[0_0_40px_rgba(255,255,255,0.4)] border-2 border-transparent text-xl"
                  >
                    ACKNOWLEDGE & ENGAGE
                  </button>
               </div>
            </div>
         </div>
      )}

      {/* --- SIDEBAR --- */}
      <aside className="hidden md:flex flex-col w-80 bg-black border-r border-cs-border z-30 shadow-2xl relative">

        {/* Brand Header */}
        <div className="p-8 border-b border-cs-border bg-black">
           <div className="flex items-center gap-5">
             <div className="relative group">
                <div className="w-14 h-14 flex items-center justify-center text-cs-red border-[3px] border-white/20 bg-zinc-900 rounded-xl transition-transform group-hover:scale-105 shadow-[0_0_20px_rgba(255,0,0,0.3)]">
                    {/* NEW LOGO: PREDATOR/JET SHAPE */}
                    <svg className="w-9 h-9 filter drop-shadow-[0_0_8px_rgba(255,0,0,0.8)]" viewBox="0 0 24 24" fill="currentColor">
                         <path d="M12 2L2 22l10-4 10 4L12 2z"/>
                    </svg>
                </div>
                {monitoringEnabled && <div className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-cs-red rounded-full animate-pulse border-2 border-black box-content shadow-[0_0_10px_rgba(255,0,0,1)]"></div>}
             </div>
             <div className="flex flex-col">
                 <h1 className="font-display font-black text-3xl tracking-tighter text-white leading-none drop-shadow-md">FALCON</h1>
                 <div className="text-[11px] text-cs-red font-bold tracking-[0.35em] mt-1 uppercase pl-0.5">Command</div>
             </div>
           </div>
        </div>

        {/* Global Stats Matrix */}
        <div className="p-6 space-y-4 bg-black">
            <div className="flex justify-between items-end mb-2 border-b border-cs-border pb-3">
                <span className="text-xs uppercase font-bold text-white tracking-widest">Global Status</span>
                <div className={`flex items-center gap-2 text-[10px] font-mono font-bold ${stats.criticalCount > 0 ? 'text-cs-red' : 'text-emerald-400'}`}>
                    <span className={`w-2.5 h-2.5 rounded-full ${stats.criticalCount > 0 ? 'bg-cs-red animate-flash' : 'bg-emerald-400 shadow-[0_0_8px_currentColor]'}`}></span>
                    {stats.criticalCount > 0 ? 'CRITICAL' : 'NOMINAL'}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
                <div className="bg-zinc-900 p-4 border border-cs-border hover:border-cs-red transition-all group relative overflow-hidden shadow-lg cursor-default">
                    <div className="absolute top-0 left-0 w-1 h-full bg-cs-red"></div>
                    <div className="text-[11px] text-gray-200 font-bold font-mono mb-2 uppercase tracking-wide">Critical</div>
                    <div className="text-3xl font-display font-bold text-white">{stats.criticalCount}</div>
                </div>
                <div className="bg-zinc-900 p-4 border border-cs-border hover:border-white transition-all group shadow-lg cursor-default">
                    <div className="text-[11px] text-gray-200 font-bold font-mono mb-2 uppercase tracking-wide">Active</div>
                    <div className="text-3xl font-display font-bold text-white">{stats.openIncidents}</div>
                </div>
            </div>

            <div className="bg-zinc-900 p-4 border border-cs-border flex items-center justify-between hover:border-white transition-all shadow-lg cursor-default">
                <div>
                     <div className="text-[11px] text-gray-200 font-bold font-mono mb-1 uppercase tracking-wide">Contained Hosts</div>
                     <div className="text-2xl font-display font-bold text-white">{stats.containedHosts}</div>
                </div>
                <svg className="w-6 h-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
        </div>

        {/* Quick Actions */}
        <div className="flex-1 px-6 space-y-3 overflow-y-auto border-t border-cs-border bg-black py-4">
            <div className="text-xs font-bold text-white uppercase tracking-widest mb-4 flex items-center gap-2">
                <svg className="w-3 h-3 text-cs-red" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                Rapid Response
            </div>

            {[
                { label: 'BRIEFING_EXEC', desc: 'Generate threat briefing', cmd: "Generate threat briefing for all CRITICAL incidents." },
                { label: 'SCAN_LATERAL', desc: 'Identify lateral movement', cmd: "Identify hosts with 'Lateral Movement' in last 24h." },
                { label: 'STATUS_CHECK', desc: 'Check containment status', cmd: "Check containment status of all critical hosts." }
            ].map((action) => (
                <button 
                    key={action.label}
                    className="w-full text-left p-3.5 bg-zinc-900 border border-cs-border hover:border-cs-red hover:bg-zinc-800 transition-all group relative overflow-hidden shadow-md"
                    onClick={() => setInput(action.cmd)}
                >
                    <div className="flex items-center justify-between mb-1.5">
                        <span className="text-xs font-mono font-bold text-white group-hover:text-cs-red transition-colors">> {action.label}</span>
                        <svg className="w-3 h-3 text-white opacity-100 transition-all transform group-hover:translate-x-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                    </div>
                    <div className="text-[11px] text-gray-300 font-medium group-hover:text-white">{action.desc}</div>
                </button>
            ))}
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-cs-border bg-black space-y-3">
            <button 
                onClick={() => setMonitoringEnabled(!monitoringEnabled)}
                className={`w-full py-4 px-4 flex items-center justify-center gap-3 text-xs font-bold transition-all uppercase tracking-widest border shadow-lg relative overflow-hidden ${
                    monitoringEnabled 
                    ? 'bg-cs-red border-cs-red text-white shadow-[0_0_20px_rgba(255,0,0,0.5)]' 
                    : 'bg-black border-cs-red text-cs-red hover:bg-cs-red hover:text-white'
                }`}
            >
                <div className={`w-2.5 h-2.5 rounded-full ${monitoringEnabled ? 'bg-white animate-pulse' : 'bg-current'}`}></div>
                <div className="flex flex-col items-start leading-none gap-1">
                    <span>{monitoringEnabled ? 'SENTINEL ACTIVE' : 'ACTIVATE SENTINEL'}</span>
                    {monitoringEnabled && <span className="text-[9px] opacity-80 font-mono tracking-normal">SCANNING EVERY 15S...</span>}
                </div>
                {monitoringEnabled && <div className="absolute inset-0 bg-white/10 animate-pulse"></div>}
            </button>

             <button 
                onClick={() => setIsSettingsOpen(true)}
                className="w-full py-3 px-4 flex items-center justify-center gap-2 text-xs font-bold text-white bg-black border border-cs-border hover:border-white hover:bg-zinc-900 transition-all uppercase tracking-wider shadow-lg"
            >
