                System Config
            </button>
        </div>
      </aside>

      {/* --- MAIN INTERFACE --- */}
      <main className="flex-1 flex flex-col relative z-10 h-screen">

        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-black border-b border-cs-border sticky top-0 z-50">
             <div className="flex items-center gap-2">
                 <div className="text-cs-red">
                    <svg className="w-8 h-8" viewBox="0 0 24 24" fill="currentColor">
                         <path d="M12 2L2 22l10-4 10 4L12 2z"/>
                    </svg>
                 </div>
                 <span className="font-display font-bold text-white tracking-wide uppercase">FALCON COMMAND</span>
             </div>
             <button onClick={() => setIsSettingsOpen(true)} className="text-white"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
        </header>

        {/* Chat Stream */}
        <div className="flex-1 overflow-y-auto p-4 md:p-10 space-y-6 scroll-smooth">
           <div className="max-w-4xl mx-auto w-full pb-4">
               {messages.map((msg) => (
                 <ChatMessage key={msg.id} message={msg} />
               ))}
               <div ref={messagesEndRef} />
           </div>
        </div>

        {/* Command Input Area */}
        <div className="p-4 md:p-10 md:pt-2 w-full">
           <div className="max-w-4xl mx-auto relative group">
              {/* Glow effect */}
              <div className="absolute -inset-0.5 bg-gradient-to-r from-cs-red/40 to-transparent rounded-lg blur opacity-50 group-hover:opacity-100 transition duration-500"></div>

              <form onSubmit={handleSendMessage} className="relative flex items-center bg-black rounded-lg shadow-2xl overflow-hidden border border-cs-border group-hover:border-cs-red/80 transition-colors">
