                  <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    disabled={isProcessing}
                    placeholder={isProcessing ? "PROCESSING STREAM..." : monitoringEnabled ? "SENTINEL ACTIVE // AWAITING COMMAND..." : "ENTER COMMAND..."}
                    className="w-full bg-transparent text-white py-6 px-2 focus:outline-none font-mono text-sm placeholder:text-gray-400 font-medium tracking-wide"
                    autoFocus
