import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats, Incident } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### FALCON INTELLIGENCE CORE // ONLINE
**Status**: COGNITIVE_ACTIVE
**Secure Link**: ESTABLISHED

I have established a direct uplink to the Falcon API. All fleet telemetry is being processed for anomalies.
**Capabilities Active**:
*   Autonomous Threat Correlation
*   Real-time Containment Authorization
*   Forensic Pattern Matching

I am monitoring the incident stream. Awaiting tactical instruction.`,
  timestamp: new Date()
};

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [criticalAlert, setCriticalAlert] = useState<Incident | null>(null);

  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;
      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 15000); 
      }
      return () => { if (interval) clearInterval(interval); };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
      } catch (e) { console.error(e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;
                  setCriticalAlert(latest);
                  const alertMsg: Message = {
                      id: crypto.randomUUID(),
                      role: 'model',
                      isAlert: true,
                      content: `### 🚨 CRITICAL ALERT: ${latest.title}
**Host**: ${latest.host_name}
**Type**: High-Confidence Breach
**Action**: Containment Protocol Recommended.

**Neural Analysis**: Threat signature matches known APT lateral movement patterns. Host isolation is the only recommended path to prevent data exfiltration.`,
                      timestamp: new Date()
                  };
                  setMessages(prev => [...prev, alertMsg]);
              }
          }
      } catch (e) { }
  };

  const processUserMessage = async (msgText: string) => {
      if (!msgText.trim() || isProcessing || !agentRef.current) return;
      const userMsg: Message = { id: crypto.randomUUID(), role: 'user', content: msgText, timestamp: new Date() };
      setMessages(prev => [...prev, userMsg]);
      setInput('');
      setIsProcessing(true);
      try {
        await agentRef.current.processMessage(msgText, (updatedMsg) => {
          setMessages(prev => {
              const exists = prev.find(m => m.id === updatedMsg.id);
              if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
              return [...prev, updatedMsg];
          });
        });
        updateStats();
      } catch (err) { console.error(err); } finally { setIsProcessing(false); }
  }

  return (
    <div className="flex h-screen bg-cs-bg text-white overflow-hidden font-sans bg-grid relative selection:bg-cs-red selection:text-white">

      {/* --- SOTA CRITICAL OVERLAY --- */}
      {criticalAlert && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-3xl animate-fadeIn">
            <div className="bg-black border-[1px] border-cs-red/50 shadow-[0_0_100px_rgba(255,0,0,0.2)] max-w-4xl w-full p-12 relative overflow-hidden group">
               <div className="absolute top-0 left-0 w-full h-[1px] bg-cs-red animate-scanline opacity-30"></div>
               <div className="relative z-10 flex flex-col items-center text-center space-y-10">
                  <div className="w-24 h-24 border-2 border-cs-red rounded-full flex items-center justify-center animate-glitch">
                     <svg className="w-12 h-12 text-cs-red" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>
                  <div>
                    <h2 className="text-5xl font-display font-black tracking-tighter uppercase mb-2">BREACH DETECTED</h2>
                    <p className="text-cs-red font-mono text-sm tracking-[0.4em] uppercase font-bold">Vector: ${criticalAlert.title}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4 w-full text-left">
                     <div className="bg-white/5 p-6 border border-white/10"><div className="text-[10px] text-gray-500 uppercase tracking-widest mb-1">Hostname</div><div className="text-2xl font-mono font-bold">{criticalAlert.host_name}</div></div>
                     <div className="bg-white/5 p-6 border border-white/10"><div className="text-[10px] text-gray-500 uppercase tracking-widest mb-1">Platform ID</div><div className="text-2xl font-mono font-bold text-cs-red">{criticalAlert.host_id.substring(0, 12)}...</div></div>
                  </div>
                  <button 
                    onClick={() => {
                        const command = `AUTHORIZE containment protocols for ${criticalAlert.host_name} (${criticalAlert.host_id})`;
                        setCriticalAlert(null);
                        processUserMessage(command);
                    }}
                    className="w-full py-6 bg-cs-red hover:bg-white hover:text-cs-red text-white font-black tracking-[0.3em] uppercase transition-all duration-500 shadow-2xl border border-transparent"
                  >
                    Execute Neural Containment
                  </button>
                  <button onClick={() => setCriticalAlert(null)} className="text-[10px] text-gray-500 uppercase tracking-[0.2em] hover:text-white transition-colors">Dismiss Intelligence Alert</button>
               </div>
            </div>
         </div>
      )}

      {/* --- SIDEBAR --- */}
      <aside className="hidden lg:flex flex-col w-80 border-r border-cs-border glass z-30 shadow-2xl">
        <div className="p-10 border-b border-cs-border">
           <div className="flex items-center gap-5 group cursor-default">
             <div className="w-14 h-14 glass flex items-center justify-center border border-cs-border relative group-hover:border-cs-red transition-all duration-700">
                <svg className="w-8 h-8 text-cs-red drop-shadow-[0_0_10px_rgba(255,0,0,0.5)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                    <path d="M12 2L2 7L12 12L22 7L12 2Z" fill="currentColor" fillOpacity="0.1"/>
                    <path d="M2 17L12 22L22 17M2 12L12 17L22 12" strokeLinejoin="round"/>
                </svg>
                <div className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-cs-red rounded-full animate-neural-pulse shadow-[0_0_10px_rgba(255,0,0,1)]"></div>
             </div>
             <div>
                <h1 className="text-3xl font-display font-black tracking-tighter leading-none">FALCON</h1>
                <p className="text-[9px] text-cs-red font-bold tracking-[0.5em] uppercase mt-1 pl-1">Command</p>
             </div>
           </div>
        </div>

        {/* Global Pulse Visualization */}
        <div className="p-8 space-y-6">
            <div className="bg-black/40 border border-cs-border p-6 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-2 opacity-20"><svg className="w-12 h-12" viewBox="0 0 24 24" fill="currentColor"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div>
                <div className="relative z-10">
                    <div className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-4 flex justify-between items-center">
                        Cyber Pulse
                        <span className={`w-2 h-2 rounded-full ${stats.criticalCount > 0 ? 'bg-cs-red animate-pulse' : 'bg-emerald-500 shadow-[0_0_8px_#10b981]'}`}></span>
                    </div>
                    <div className="flex items-end gap-3">
                        <span className="text-4xl font-display font-black">{stats.criticalCount}</span>
                        <span className="text-[10px] font-mono text-gray-400 mb-1.5 uppercase tracking-tighter">Critical Threats</span>
                    </div>
                    <div className="mt-4 h-1 bg-white/5 overflow-hidden">
                        <div className={`h-full transition-all duration-1000 ${stats.criticalCount > 0 ? 'bg-cs-red w-full' : 'bg-emerald-500 w-[10%]'}`}></div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div className="glass p-5 border-white/5 hover:border-white/20 transition-all cursor-default group">
                    <div className="text-[9px] text-gray-500 uppercase font-black tracking-widest mb-2 group-hover:text-white transition-colors">Incidents</div>
                    <div className="text-2xl font-display font-bold">{stats.openIncidents}</div>
                </div>
                <div className="glass p-5 border-white/5 hover:border-cs-red transition-all cursor-default group">
                    <div className="text-[9px] text-gray-500 uppercase font-black tracking-widest mb-2 group-hover:text-cs-red transition-colors">Contained</div>
                    <div className="text-2xl font-display font-bold">{stats.containedHosts}</div>
                </div>
            </div>
        </div>

        {/* Rapid Deployment Sector */}
        <div className="flex-1 px-8 space-y-3 overflow-y-auto mt-4 border-t border-cs-border py-8">
            <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] mb-4">Tactical Routines</h3>
            {['BRIEFING_EXEC', 'SCAN_LATERAL', 'ENVIRONMENT_PULSE'].map((label) => (
                <button 
                  key={label}
                  onClick={() => setInput(label.replace('_', ' '))}
                  className="w-full text-left p-4 glass border-white/5 hover:border-cs-red hover:bg-cs-red/5 group transition-all duration-500"
                >
                    <div className="flex items-center justify-between">
                        <span className="text-[11px] font-mono font-bold group-hover:text-cs-red transition-colors">> {label}</span>
