        <div className="p-12 pt-0 w-full relative z-20">
           <div className="max-w-5xl mx-auto">
              <form onSubmit={handleSendMessage} className="relative group glass border-white/10 hover:border-cs-red transition-all duration-700">
                  <div className="absolute inset-0 bg-cs-red/5 opacity-0 group-focus-within:opacity-100 transition-opacity pointer-events-none"></div>
