import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, ToolCallDetails } from '../types';

interface ChatMessageProps {
  message: Message;
}

const ToolStream: React.FC<{ tools: ToolCallDetails[] }> = ({ tools }) => (
  <div className="mb-6 space-y-3 font-mono text-[10px]">
    {tools.map((t, idx) => (
      <div key={idx} className="bg-black/80 border border-white/10 p-4 relative overflow-hidden group">
        <div className="absolute top-0 left-0 w-[1px] h-full bg-cs-red"></div>
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full ${t.status === 'pending' ? 'bg-cs-red animate-pulse' : t.status === 'error' ? 'bg-red-500' : 'bg-emerald-400 shadow-[0_0_10px_currentColor]'}`}></div>
          <div className="flex-1 flex justify-between items-center">
             <div className="flex gap-3">
                <span className="text-gray-600 uppercase tracking-widest font-black">Call_Ref:</span>
                <span className="text-white font-black">{t.functionName}</span>
             </div>
             <div className="flex gap-3">
                <span className="text-gray-600 uppercase tracking-widest">Args:</span>
                <span className="text-gray-400 truncate max-w-[150px]">{JSON.stringify(t.args)}</span>
             </div>
          </div>
