                </div>
                <svg className="w-10 h-10 text-zinc-500 group-hover:text-emerald-400 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
            </div>
        </div>

        {/* Clickable Playbooks Console */}
        <div className="flex-1 px-10 space-y-4 overflow-y-auto mt-2 border-t border-cs-border py-10 bg-zinc-900/60 custom-scrollbar">
            <h3 className="text-[12px] font-black text-white uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
               <span className="w-3 h-3 bg-cs-red rounded-sm shadow-[0_0_10px_#ff2d2d]"></span> Tactical Playbooks
            </h3>

            {PLAYBOOKS.map((pb) => (
                <button 
                  key={pb.id} 
                  onClick={() => runPlaybook(pb)}
                  disabled={isProcessing}
                  className={`w-full text-left p-6 bg-zinc-800 border-2 transition-all duration-300 cursor-pointer rounded-sm shadow-sm group active:scale-[0.98] ${
                    activePlaybookId === pb.id ? 'border-cs-red bg-cs-red/20' : 'border-white/5 hover:border-cs-red hover:bg-zinc-700'
                  } ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[12px] font-mono font-black text-white group-hover:text-cs-red transition-colors">{pb.name}</span>
