                    <span className="text-lg font-mono font-bold text-white tracking-tighter uppercase">Protocol_FIC_V3_Stable</span>
                </div>
            </div>
            <div className="flex items-center gap-10">
                <div className="flex flex-col items-end">
                    <span className="text-[11px] font-black text-zinc-400 uppercase tracking-widest">Connection</span>
                    <span className="text-[12px] font-mono font-bold text-emerald-400 animate-pulse">ENCRYPTED // LOW_LATENCY</span>
                </div>
            </div>
        </header>

