                  </div>
              </div>
           </div>
        </div>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={(newConfig) => setConfig(newConfig)} />
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats, Incident } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### 🦅 INTELLIGENCE CORE ONLINE
**Neural Engine**: Gemini 3 Pro
**Uplink**: Real-time Falcon Telemetry

Select a Playbook or enter a strategic command to begin analysis.`,
  timestamp: new Date()
};

const PLAYBOOKS = [
  { 
    id: 'PB-LAT', 
    name: 'LATERAL_SWEEP', 
    cmd: 'Perform a Lateral Movement Sweep: Correlate all active incidents to find shared user accounts, IP hop-points, and administrative credential usage across the fleet.',
    desc: 'Map attack progression between hosts.' 
  },
  { 
    id: 'PB-ROOT', 
    name: 'ROOT_CAUSE_AI', 
    cmd: 'Execute Root Cause Analysis: For the most recent critical incident, analyze the full process tree and behavioral detections to identify the initial entry point.',
    desc: 'ML-based process chain reconstruction.' 
  },
  { 
    id: 'PB-EXFIL', 
    name: 'EXFIL_HUNTER', 
    cmd: 'Data Exfiltration Hunt: Scan for large network outbound spikes, cloud storage connections, and suspicious archiving tools across high-value assets.',
    desc: 'Identify data theft in progress.' 
  },
  { 
    id: 'PB-IDEN', 
    name: 'IDENTITY_VALIDATOR', 
    cmd: 'Check Identity Integrity: Review login history for all hosts with active alerts. Flag MFA bypasses, abnormal login hours, and new local admin creations.',
    desc: 'Verify user credentials & MFA status.' 
  },
  { 
    id: 'PB-PERSIST', 
    name: 'PERSISTENCE_SCAN', 
    cmd: 'Persistence Mechanism Audit: Search for new service installations, registry modifications, and scheduled tasks across the fleet within the last 24 hours.',
    desc: 'Find backdoors and autostart keys.' 
  },
  { 
    id: 'PB-HYG', 
    name: 'FLEET_HYGIENE', 
    cmd: 'Run Fleet Hygiene Audit: Get statistics on unpatched critical vulnerabilities and missing sensor updates for the top 5 most critical assets.',
    desc: 'Assess exposure to known CVEs.' 
  }
];

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [criticalAlert, setCriticalAlert] = useState<Incident | null>(null);

  const [riskScore, setRiskScore] = useState(0);
  const [activePlaybookId, setActivePlaybookId] = useState<string | null>(null);

  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'auto' });
  }, [messages]);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;
      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 15000); 
      }
      return () => { if (interval) clearInterval(interval); };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
          const calculatedRisk = Math.min(100, (s.criticalCount * 15) + (s.openIncidents * 2));
          setRiskScore(calculatedRisk);
      } catch (e) { console.error(e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;
                  setCriticalAlert(latest);

                  setActivePlaybookId('PB-ROOT');
                  const command = `AUTOMATED PLAYBOOK: Perform forensic analysis on critical incident ${latest.incident_id} for host ${latest.host_name}.`;
                  processUserMessage(command, true);
                  setTimeout(() => setActivePlaybookId(null), 5000);
              }
          }
      } catch (e) { }
  };

  const processUserMessage = async (msgText: string, isAutomated: boolean = false) => {
      if (!msgText.trim() || isProcessing || !agentRef.current) return;

      const userMsg: Message = { 
        id: crypto.randomUUID(), 
        role: isAutomated ? 'system' : 'user', 
        content: msgText, 
        timestamp: new Date() 
      };

      setMessages(prev => [...prev, userMsg]);
      setInput('');
      setIsProcessing(true);

      try {
        await agentRef.current.processMessage(msgText, (updatedMsg) => {
          setMessages(prev => {
              const exists = prev.find(m => m.id === updatedMsg.id);
              if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
              return [...prev, updatedMsg];
          });
        });
        updateStats();
      } catch (err) { console.error(err); } finally { setIsProcessing(false); }
  }

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      processUserMessage(input);
  };

  const runPlaybook = (pb: typeof PLAYBOOKS[0]) => {
      if (isProcessing) return;
      setActivePlaybookId(pb.id);
      processUserMessage(pb.cmd, true);
      setTimeout(() => setActivePlaybookId(null), 3000);
  }

  return (
    <div className="flex h-screen bg-cs-bg text-zinc-100 overflow-hidden font-sans bg-grid relative selection:bg-cs-red selection:text-white">

      {/* --- CRITICAL OVERLAY --- */}
      {criticalAlert && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-3xl">
            <div className="bg-zinc-800 border-[2px] border-cs-red shadow-[0_0_150px_rgba(255,45,45,0.4)] max-w-5xl w-full p-16 relative overflow-hidden rounded-lg">
               <div className="absolute top-0 left-0 w-full h-[2px] bg-cs-red animate-scanline"></div>
               <div className="relative z-10 flex flex-col items-center text-center space-y-12">
                  <div className="w-24 h-24 border-2 border-cs-red rounded-full flex items-center justify-center shadow-[0_0_30px_rgba(255,45,45,0.5)]">
                     <svg className="w-12 h-12 text-cs-red" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>
                  <div>
                    <h2 className="text-6xl font-display font-black tracking-tighter uppercase mb-4 text-white">ACTIVE COMPROMISE</h2>
                    <p className="text-cs-red font-mono text-xl tracking-[0.5em] uppercase font-bold animate-pulse">INCIDENT: {criticalAlert.incident_id}</p>
                  </div>
                  <div className="grid grid-cols-3 gap-6 w-full text-left">
                     <div className="bg-zinc-700/50 p-8 border border-white/10"><div className="text-[11px] text-zinc-400 uppercase tracking-widest mb-2 font-black">Target Asset</div><div className="text-2xl font-mono font-bold text-white">{criticalAlert.host_name}</div></div>
                     <div className="bg-zinc-700/50 p-8 border border-white/10"><div className="text-[11px] text-zinc-400 uppercase tracking-widest mb-2 font-black">Risk Velocity</div><div className="text-2xl font-mono font-bold text-cs-red">HIGH_INCREASE</div></div>
                     <div className="bg-zinc-700/50 p-8 border border-white/10"><div className="text-[11px] text-zinc-400 uppercase tracking-widest mb-2 font-black">Vector Type</div><div className="text-2xl font-mono font-bold text-white">LATERAL_MOV</div></div>
                  </div>
                  <div className="flex gap-6 w-full">
                    <button 
                        onClick={() => {
                            const command = `AUTHORIZE containment protocols for ${criticalAlert.host_name} (${criticalAlert.host_id})`;
                            setCriticalAlert(null);
                            processUserMessage(command);
                        }}
                        className="flex-1 py-8 bg-cs-red hover:bg-white hover:text-cs-red text-white font-black tracking-[0.4em] uppercase transition-all duration-500 shadow-2xl border border-transparent text-xl"
                    >
                        Initiate Containment
                    </button>
                    <button onClick={() => setCriticalAlert(null)} className="px-12 py-8 glass border-white/10 hover:border-white transition-all text-xs font-black uppercase tracking-widest">Acknowledge</button>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* --- SIDEBAR --- */}
      <aside className="hidden xl:flex flex-col w-[26rem] border-r border-cs-border glass z-30 shadow-2xl relative overflow-hidden">

        {/* Header - Fixed Height and Padding to prevent clipping */}
        <div className="p-10 border-b border-cs-border bg-zinc-800 min-h-[220px]">
           <div className="flex flex-col gap-8 h-full">
             <div className="flex items-center gap-6 group cursor-default h-20">
                <div className="flex-shrink-0 w-16 h-16 bg-zinc-900 flex items-center justify-center border-2 border-cs-border relative group-hover:border-cs-red transition-all duration-700 shadow-lg rounded-sm overflow-visible">
                    <svg className="w-10 h-10 text-cs-red" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                        <path d="M12 2L2 7L12 12L22 7L12 2Z" fill="currentColor" fillOpacity="0.1"/>
                        <path d="M2 17L12 22L22 17M2 12L12 17L22 12" strokeLinejoin="round"/>
                    </svg>
                    <div className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-cs-red rounded-full animate-neural-pulse shadow-[0_0_15px_#ff2d2d]"></div>
                </div>
                <div className="flex flex-col justify-center">
                    <h1 className="text-5xl font-display font-black tracking-tighter leading-none text-white overflow-visible">FALCON</h1>
                    <p className="text-[11px] text-cs-red font-black tracking-[0.6em] uppercase mt-3 pl-3 border-l-2 border-cs-red whitespace-nowrap">Intelligence Core</p>
                </div>
             </div>

             {/* Risk Index */}
             <div className="pt-2">
                <div className="flex justify-between items-end mb-4">
                    <span className="text-[12px] font-black text-zinc-300 uppercase tracking-widest">Fleet Exposure Index</span>
                    <span className={`text-3xl font-mono font-black ${riskScore > 50 ? 'text-cs-red' : 'text-emerald-400'}`}>{riskScore}%</span>
                </div>
                <div className="h-3 w-full bg-zinc-900 rounded-full overflow-hidden border border-white/10">
                    <div 
                        className={`h-full transition-all duration-1000 ease-out shadow-[0_0_15px_currentColor] ${riskScore > 70 ? 'bg-cs-red' : riskScore > 30 ? 'bg-amber-400' : 'bg-emerald-400'}`}
                        style={{ width: `${riskScore}%` }}
                    ></div>
                </div>
             </div>
           </div>
        </div>

        {/* Metrics */}
        <div className="p-10 space-y-6">
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-zinc-700 p-6 border border-white/10 hover:border-cs-red transition-all duration-300 group relative rounded-sm shadow-md">
                    <div className="text-[11px] text-zinc-300 uppercase font-black tracking-widest mb-3 group-hover:text-cs-red transition-colors">Critical</div>
                    <div className="text-5xl font-display font-black text-white">{stats.criticalCount}</div>
                    {stats.criticalCount > 0 && <div className="absolute top-2 right-2 w-2.5 h-2.5 bg-cs-red rounded-full animate-ping"></div>}
                </div>
                <div className="bg-zinc-700 p-6 border border-white/10 hover:border-white transition-all duration-300 group rounded-sm shadow-md">
                    <div className="text-[11px] text-zinc-300 uppercase font-black tracking-widest mb-3 group-hover:text-white transition-colors">Active</div>
                    <div className="text-5xl font-display font-black text-white">{stats.openIncidents}</div>
                </div>
            </div>

            <div className="bg-zinc-700 p-6 border border-white/10 flex items-center justify-between hover:border-emerald-400 transition-all duration-300 group rounded-sm shadow-md">
                <div>
                    <div className="text-[11px] text-zinc-300 uppercase font-black tracking-widest mb-2 group-hover:text-emerald-400">Contained Assets</div>
                    <div className="text-4xl font-display font-black text-white">{stats.containedHosts}</div>
                </div>
                <svg className="w-10 h-10 text-zinc-500 group-hover:text-emerald-400 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
            </div>
        </div>

        {/* Playbooks */}
        <div className="flex-1 px-10 space-y-4 overflow-y-auto mt-2 border-t border-cs-border py-10 bg-zinc-900/60 custom-scrollbar">
            <h3 className="text-[12px] font-black text-white uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
               <span className="w-3 h-3 bg-cs-red rounded-sm shadow-[0_0_10px_#ff2d2d]"></span> Tactical Playbooks
            </h3>

            {PLAYBOOKS.map((pb) => (
                <button 
                  key={pb.id} 
                  onClick={() => runPlaybook(pb)}
                  disabled={isProcessing}
                  className={`w-full text-left p-6 bg-zinc-800 border-2 transition-all duration-200 cursor-pointer rounded-sm shadow-sm group ${
                    activePlaybookId === pb.id ? 'border-cs-red bg-cs-red/20' : 'border-white/5 hover:border-cs-red hover:bg-zinc-700'
                  } ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[12px] font-mono font-black text-white group-hover:text-cs-red transition-colors">{pb.name}</span>
                        <span className={`text-[9px] font-black px-2 py-0.5 border ${activePlaybookId === pb.id ? 'bg-cs-red border-cs-red text-white' : 'border-zinc-600 text-zinc-400'}`}>
                          {activePlaybookId === pb.id ? 'EXECUTING' : 'READY'}
                        </span>
                    </div>
                    <p className="text-[11px] text-zinc-400 font-medium group-hover:text-zinc-200 leading-relaxed">{pb.desc}</p>
                </button>
            ))}
        </div>

        {/* Global Controls */}
        <div className="p-10 border-t border-cs-border space-y-4 bg-zinc-800">
            <button 
                onClick={() => setMonitoringEnabled(!monitoringEnabled)}
                className={`w-full py-7 flex flex-col items-center justify-center gap-2 text-[12px] font-black tracking-[0.4em] uppercase transition-all duration-500 border-2 shadow-xl rounded-sm ${
                    monitoringEnabled ? 'bg-cs-red border-cs-red text-white' : 'bg-zinc-900 border-zinc-700 text-zinc-400 hover:text-white hover:border-zinc-500'
                }`}
            >
                <div className="flex items-center gap-3">
                    <div className={`w-3.5 h-3.5 rounded-full ${monitoringEnabled ? 'bg-white animate-pulse' : 'bg-current'}`}></div>
                    {monitoringEnabled ? 'SENTINEL_ACTIVE' : 'ACTIVATE_SENTINEL'}
                </div>
                {monitoringEnabled && <span className="text-[9px] opacity-80 tracking-[0.2em] font-mono">NEURAL SCAN IN PROGRESS...</span>}
            </button>
            <div className="flex gap-4">
                <button onClick={() => setIsSettingsOpen(true)} className="flex-1 text-center text-[11px] font-black text-zinc-300 hover:text-white border-2 border-zinc-700 py-4 transition-colors uppercase tracking-widest rounded-sm bg-zinc-900">Config</button>
                <button onClick={() => window.location.reload()} className="flex-1 text-center text-[11px] font-black text-zinc-300 hover:text-cs-red border-2 border-zinc-700 py-4 transition-colors uppercase tracking-widest rounded-sm bg-zinc-900">Reboot</button>
            </div>
        </div>
