  { id: 'PB-PERSIST', name: 'PERSISTENCE', cmd: 'Persistence Audit: Search for new service installations and scheduled tasks across the fleet.', desc: 'Find backdoors.' },
  { id: 'PB-RANS', name: 'RANSOM_WATCH', cmd: 'Ransomware Defense: Check for Shadow Copy deletion and unusual encryption/archiving activity.', desc: 'Prevent encryption.' },
  { id: 'PB-VULN', name: 'VULN_MAPPER', cmd: 'CVE Mapping: Cross-reference active alerts with known critical vulnerabilities (CVEs) on affected hosts.', desc: 'Asset vulnerability link.' },
  { id: 'PB-SCRIPT', name: 'SCRIPT_SCAN', cmd: 'Script Audit: Analyze all PowerShell, WMI, and BITSAdmin execution logs for suspicious obfuscation.', desc: 'Check living-off-the-land.' },
  { id: 'PB-ZERO', name: 'ZERO_TRUST', cmd: 'Zero-Trust Review: Verify conditional access failures and failed MFA attempts for high-value targets.', desc: 'Access integrity.' },
  { id: 'PB-DLP', name: 'DLP_CHECK', cmd: 'Data Loss Audit: Monitor for sensitive file access and removable media usage on flagged assets.', desc: 'Monitor sensitive data.' },
  { id: 'PB-INJECT', name: 'INJECT_HUNT', cmd: 'Code Injection Scan: Search for process hollowing and reflective DLL injection signatures.', desc: 'Find memory-only threats.' },
  { id: 'PB-HYG', name: 'HYGIENE', cmd: 'Fleet Hygiene: Identify assets with outdated sensors or critical patches missing.', desc: 'Assess security posture.' },
  { id: 'PB-CLOUD', name: 'CLOUD_DRIFT', cmd: 'Cloud Security Audit: Analyze drift in container permissions and unusual cloud API calls.', desc: 'Cloud/Container drift.' },
  { id: 'PB-BEACON', name: 'C2_BEACON', cmd: 'C2 Beaconing Hunt: Identify hosts making repetitive, low-volume outbound connections to unknown IPs.', desc: 'Find Command & Control.' }
];

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [criticalAlert, setCriticalAlert] = useState<Incident | null>(null);

  const [riskScore, setRiskScore] = useState(0);
  const [activePlaybookId, setActivePlaybookId] = useState<string | null>(null);

  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'auto' });
  }, [messages]);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;
      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 15000); 
      }
      return () => { if (interval) clearInterval(interval); };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
          const calculatedRisk = Math.min(100, (s.criticalCount * 15) + (s.openIncidents * 2));
          setRiskScore(calculatedRisk);
      } catch (e) { console.error(e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;
                  setCriticalAlert(latest);

                  setActivePlaybookId('PB-ROOT');
                  const command = `AUTOMATED PLAYBOOK: Perform forensic analysis on critical incident ${latest.incident_id} for host ${latest.host_name}.`;
                  processUserMessage(command, true);
                  setTimeout(() => setActivePlaybookId(null), 5000);
              }
          }
      } catch (e) { }
  };

  const processUserMessage = async (msgText: string, isAutomated: boolean = false) => {
      if (!msgText.trim() || isProcessing || !agentRef.current) return;

      const userMsg: Message = { 
        id: crypto.randomUUID(), 
        role: isAutomated ? 'system' : 'user', 
        content: msgText, 
        timestamp: new Date() 
      };

      setMessages(prev => [...prev, userMsg]);
      setInput('');
      setIsProcessing(true);

      try {
        await agentRef.current.processMessage(msgText, (updatedMsg) => {
          setMessages(prev => {
              const exists = prev.find(m => m.id === updatedMsg.id);
              if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
              return [...prev, updatedMsg];
          });
        });
        updateStats();
      } catch (err) { console.error(err); } finally { setIsProcessing(false); }
  }

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      processUserMessage(input);
  };

  const runPlaybook = (pb: typeof PLAYBOOKS[0]) => {
      if (isProcessing) return;
      setActivePlaybookId(pb.id);
      processUserMessage(pb.cmd, true);
      setTimeout(() => setActivePlaybookId(null), 3000);
  }

  return (
    <div className="flex h-screen bg-cs-bg text-zinc-100 overflow-hidden font-sans bg-grid relative selection:bg-cs-red selection:text-white">

      {/* --- CRITICAL OVERLAY --- */}
      {criticalAlert && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-3xl">
            <div className="bg-zinc-800 border-[2px] border-cs-red shadow-[0_0_150px_rgba(255,45,45,0.4)] max-w-5xl w-full p-16 relative overflow-hidden rounded-lg">
               <div className="absolute top-0 left-0 w-full h-[2px] bg-cs-red animate-scanline"></div>
               <div className="relative z-10 flex flex-col items-center text-center space-y-12">
                  <div className="w-24 h-24 border-2 border-cs-red rounded-full flex items-center justify-center shadow-[0_0_30px_rgba(255,45,45,0.5)]">
                     <svg className="w-12 h-12 text-cs-red" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>
                  <div>
                    <h2 className="text-6xl font-display font-black tracking-tighter uppercase mb-4 text-white">ACTIVE COMPROMISE</h2>
                    <p className="text-cs-red font-mono text-xl tracking-[0.5em] uppercase font-bold animate-pulse">INCIDENT: {criticalAlert.incident_id}</p>
                  </div>
                  <div className="grid grid-cols-3 gap-6 w-full text-left">
                     <div className="bg-zinc-700/50 p-8 border border-white/10"><div className="text-[11px] text-zinc-400 uppercase tracking-widest mb-2 font-black">Target Asset</div><div className="text-2xl font-mono font-bold text-white">{criticalAlert.host_name}</div></div>
                     <div className="bg-zinc-700/50 p-8 border border-white/10"><div className="text-[11px] text-zinc-400 uppercase tracking-widest mb-2 font-black">Risk Velocity</div><div className="text-2xl font-mono font-bold text-cs-red">HIGH_INCREASE</div></div>
                     <div className="bg-zinc-700/50 p-8 border border-white/10"><div className="text-[11px] text-zinc-400 uppercase tracking-widest mb-2 font-black">Vector Type</div><div className="text-2xl font-mono font-bold text-white">LATERAL_MOV</div></div>
                  </div>
                  <div className="flex gap-6 w-full">
                    <button 
                        onClick={() => {
                            const command = `AUTHORIZE containment protocols for ${criticalAlert.host_name} (${criticalAlert.host_id})`;
                            setCriticalAlert(null);
                            processUserMessage(command);
                        }}
                        className="flex-1 py-8 bg-cs-red hover:bg-white hover:text-cs-red text-white font-black tracking-[0.4em] uppercase transition-all duration-500 shadow-2xl border border-transparent text-xl"
                    >
                        Initiate Containment
                    </button>
                    <button onClick={() => setCriticalAlert(null)} className="px-12 py-8 glass border-white/10 hover:border-white transition-all text-xs font-black uppercase tracking-widest">Acknowledge</button>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* --- SIDEBAR --- */}
      <aside className="hidden xl:flex flex-col w-[28rem] border-r border-cs-border glass z-30 shadow-2xl relative overflow-hidden">

        {/* Compact Header */}
        <div className="p-8 border-b border-cs-border bg-zinc-800">
           <div className="flex flex-col gap-6">
             <div className="flex items-center gap-5 group cursor-default">
                <div className="flex-shrink-0 w-14 h-14 bg-zinc-900 flex items-center justify-center border-2 border-cs-border relative group-hover:border-cs-red transition-all duration-700 shadow-lg rounded-sm">
                    <svg className="w-8 h-8 text-cs-red" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                        <path d="M12 2L2 7L12 12L22 7L12 2Z" fill="currentColor" fillOpacity="0.1"/>
                        <path d="M2 17L12 22L22 17M2 12L12 17L22 12" strokeLinejoin="round"/>
                    </svg>
                    <div className="absolute -top-1 -right-1 w-3 h-3 bg-cs-red rounded-full animate-neural-pulse shadow-[0_0_12px_#ff2d2d]"></div>
                </div>
                <div>
                    <h1 className="text-4xl font-display font-black tracking-tighter leading-none text-white overflow-visible">FALCON</h1>
                    <p className="text-[10px] text-cs-red font-black tracking-[0.5em] uppercase mt-2 pl-2 border-l-2 border-cs-red whitespace-nowrap">Intelligence Core</p>
                </div>
             </div>

             {/* Risk Index */}
             <div>
                <div className="flex justify-between items-end mb-2">
                    <span className="text-[11px] font-black text-zinc-400 uppercase tracking-widest">Fleet Risk Velocity</span>
                    <span className={`text-2xl font-mono font-black ${riskScore > 50 ? 'text-cs-red' : 'text-emerald-400'}`}>{riskScore}%</span>
                </div>
                <div className="h-2 w-full bg-zinc-900 rounded-full overflow-hidden border border-white/10">
                    <div 
                        className={`h-full transition-all duration-1000 ease-out shadow-[0_0_15px_currentColor] ${riskScore > 70 ? 'bg-cs-red' : riskScore > 30 ? 'bg-amber-400' : 'bg-emerald-400'}`}
                        style={{ width: `${riskScore}%` }}
                    ></div>
                </div>
             </div>
           </div>
        </div>

        {/* Compact Metrics */}
        <div className="px-8 py-6 space-y-4">
            <div className="grid grid-cols-3 gap-3">
                <div className="bg-zinc-700 p-4 border border-white/10 relative rounded-sm shadow-md">
                    <div className="text-[9px] text-zinc-400 uppercase font-black tracking-widest mb-1">Critical</div>
                    <div className="text-2xl font-display font-black text-white">{stats.criticalCount}</div>
                    {stats.criticalCount > 0 && <div className="absolute top-1 right-1 w-2 h-2 bg-cs-red rounded-full animate-ping"></div>}
