);

export const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const isAlert = message.isAlert;

  if (message.role === 'system') {
    return (
      <div className="flex justify-center my-10">
        <div className="bg-red-600 text-white px-8 py-3 text-[10px] font-black uppercase tracking-[0.4em] shadow-[0_0_50px_rgba(255,0,0,0.4)]">
           {message.content}
        </div>
      </div>
    );
  }

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} group`}>
      <div className={`max-w-[85%] flex gap-8 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-12 h-12 glass flex items-center justify-center border transition-all duration-300 ${
            isUser ? 'border-cs-border' : 
            isAlert ? 'border-cs-red shadow-[0_0_20px_rgba(255,0,0,0.3)]' : 'border-cs-border group-hover:border-cs-red'
        }`}>
          {isUser ? (
             <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
          ) : (
            <div className={`font-display font-black text-xl ${isAlert ? 'text-cs-red' : 'text-white'}`}>C</div>
          )}
        </div>

        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} flex-1 min-w-0`}>
          <div className="flex items-center gap-4 mb-3 text-[10px] font-mono tracking-[0.2em] uppercase opacity-40 group-hover:opacity-100 transition-opacity">
             <span className={`font-black ${isAlert ? 'text-cs-red' : 'text-white'}`}>
               {isUser ? 'Operator' : isAlert ? 'Alert_Core' : 'CORE_LOGIC'}
             </span>
             <span className="text-zinc-500">
               {message.timestamp.toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
             </span>
          </div>

          <div className={`p-8 glass transition-all duration-300 rounded-sm relative overflow-hidden ${
            isUser 
              ? 'border-white/10 group-hover:border-white/30' 
              : isAlert 
                ? 'border-cs-red bg-cs-red/5' 
                : 'border-white/5 group-hover:border-cs-red/40'
          }`}>
            {!isUser && <div className="absolute top-0 left-0 w-full h-[1px] bg-white/5 animate-scanline pointer-events-none"></div>}

            {message.toolCalls && <ToolStream tools={message.toolCalls} />}

            {message.isThinking && !message.content ? (
                 <div className="flex items-center gap-5 py-2 font-mono text-[10px] text-cs-red font-black tracking-[0.4em] uppercase">
                    <span className="flex gap-2">
                      <div className="w-2 h-2 bg-cs-red animate-pulse"></div>
                      <div className="w-2 h-2 bg-cs-red animate-pulse delay-75"></div>
                      <div className="w-2 h-2 bg-cs-red animate-pulse delay-150"></div>
                    </span>
                    ANALYZING...
                 </div>
            ) : (
              <ReactMarkdown 
                className="markdown-content font-sans text-sm text-zinc-300 space-y-6 leading-relaxed"
                components={{
                  h3: ({node, ...props}) => <h3 className="text-[12px] font-black text-white mt-8 mb-4 tracking-[0.3em] uppercase flex items-center gap-3 border-l-4 border-cs-red pl-4" {...props} />,
                  ul: ({node, ...props}) => <ul className="space-y-4 my-4" {...props} />,
                  li: ({node, ...props}) => <li className="flex items-start gap-4 text-zinc-400 group/li transition-colors hover:text-white" {...props}><div className="mt-2.5 w-1.5 h-1.5 bg-cs-red transition-shadow" /> <span className="flex-1">{props.children}</span></li>,
                  code: ({node, ...props}) => <code className="bg-white/5 text-white px-2 py-1 font-mono text-[11px] border border-white/10" {...props} />,
                  pre: ({node, ...props}) => <pre className="bg-black p-6 overflow-x-auto text-[11px] font-mono border border-white/5 my-6 text-zinc-400" {...props} />,
                  strong: ({node, ...props}) => <strong className="font-black text-white" {...props} />,
                  p: ({node, ...props}) => <p className="leading-8" {...props} />
                }}
              >
                {message.content}
              </ReactMarkdown>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats, Incident } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### COMMAND CENTER ONLINE
Select a Tactical Playbook or enter a command to begin.`,
  timestamp: new Date()
};

const PLAYBOOKS = [
  { id: 'PB-INFO', name: 'HOST_INFO', cmd: 'Get Host Intelligence: Retrieve full system profile, network interfaces, and last logged-on user for a specific asset.', desc: 'Full asset discovery.' },
  { id: 'PB-LAT', name: 'LATERAL_SWEEP', cmd: 'Perform a Lateral Movement Sweep: Correlate active incidents to find shared user accounts and IP hop-points.', desc: 'Map attack progression.' },
  { id: 'PB-ROOT', name: 'ROOT_CAUSE_AI', cmd: 'Execute Root Cause Analysis: Analyze the process tree and behavioral detections for the most recent critical incident.', desc: 'ML process reconstruction.' },
  { id: 'PB-EXFIL', name: 'EXFIL_HUNTER', cmd: 'Data Exfiltration Hunt: Scan for large network outbound spikes and cloud storage connections.', desc: 'Identify data theft.' },
  { id: 'PB-IDEN', name: 'IDENTITY_AUDIT', cmd: 'Check Identity Integrity: Flag MFA bypasses, abnormal login hours, and new local admin creations.', desc: 'Verify user credentials.' },
  { id: 'PB-PERSIST', name: 'PERSISTENCE', cmd: 'Persistence Audit: Search for new service installations and scheduled tasks across the fleet.', desc: 'Find backdoors.' },
  { id: 'PB-RANS', name: 'RANSOM_WATCH', cmd: 'Ransomware Defense: Check for Shadow Copy deletion and unusual encryption/archiving activity.', desc: 'Prevent encryption.' },
  { id: 'PB-VULN', name: 'VULN_MAPPER', cmd: 'CVE Mapping: Cross-reference active alerts with known critical vulnerabilities (CVEs) on affected hosts.', desc: 'Asset vulnerability link.' },
  { id: 'PB-SCRIPT', name: 'SCRIPT_SCAN', cmd: 'Script Audit: Analyze all PowerShell, WMI, and BITSAdmin execution logs for suspicious obfuscation.', desc: 'Check living-off-the-land.' },
  { id: 'PB-ZERO', name: 'ZERO_TRUST', cmd: 'Zero-Trust Review: Verify conditional access failures and failed MFA attempts for high-value targets.', desc: 'Access integrity.' },
  { id: 'PB-DLP', name: 'DLP_CHECK', cmd: 'Data Loss Audit: Monitor for sensitive file access and removable media usage on flagged assets.', desc: 'Monitor sensitive data.' },
  { id: 'PB-INJECT', name: 'INJECT_HUNT', cmd: 'Code Injection Scan: Search for process hollowing and reflective DLL injection signatures.', desc: 'Find memory-only threats.' },
  { id: 'PB-HYG', name: 'HYGIENE', cmd: 'Fleet Hygiene: Identify assets with outdated sensors or critical patches missing.', desc: 'Assess security posture.' },
  { id: 'PB-CLOUD', name: 'CLOUD_DRIFT', cmd: 'Cloud Security Audit: Analyze drift in container permissions and unusual cloud API calls.', desc: 'Cloud/Container drift.' },
  { id: 'PB-BEACON', name: 'C2_BEACON', cmd: 'C2 Beaconing Hunt: Identify hosts making repetitive, low-volume outbound connections to unknown IPs.', desc: 'Find Command & Control.' }
];

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [criticalAlert, setCriticalAlert] = useState<Incident | null>(null);

  const [riskScore, setRiskScore] = useState(0);
  const [activePlaybookId, setActivePlaybookId] = useState<string | null>(null);

  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'auto' });
  }, [messages]);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;
      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 15000); 
      }
      return () => { if (interval) clearInterval(interval); };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
          const calculatedRisk = Math.min(100, (s.criticalCount * 15) + (s.openIncidents * 2));
          setRiskScore(calculatedRisk);
      } catch (e) { console.error(e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;
                  setCriticalAlert(latest);

                  setActivePlaybookId('PB-ROOT');
                  const command = `AUTOMATED PLAYBOOK: Perform forensic analysis on critical incident ${latest.incident_id} for host ${latest.host_name}.`;
                  processUserMessage(command, true);
                  setTimeout(() => setActivePlaybookId(null), 5000);
              }
          }
      } catch (e) { }
  };

  const processUserMessage = async (msgText: string, isAutomated: boolean = false) => {
      if (!msgText.trim() || isProcessing || !agentRef.current) return;

      const userMsg: Message = { 
        id: crypto.randomUUID(), 
        role: isAutomated ? 'system' : 'user', 
        content: msgText, 
        timestamp: new Date() 
      };

      setMessages(prev => [...prev, userMsg]);
      setInput('');
      setIsProcessing(true);

      try {
        await agentRef.current.processMessage(msgText, (updatedMsg) => {
          setMessages(prev => {
              const exists = prev.find(m => m.id === updatedMsg.id);
              if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
              return [...prev, updatedMsg];
          });
        });
        updateStats();
      } catch (err) { console.error(err); } finally { setIsProcessing(false); }
  }

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      processUserMessage(input);
  };

  const runPlaybook = (pb: typeof PLAYBOOKS[0]) => {
      if (isProcessing) return;
      setActivePlaybookId(pb.id);
      processUserMessage(pb.cmd, true);
      setTimeout(() => setActivePlaybookId(null), 3000);
  }

  return (
    <div className="flex h-screen bg-cs-bg text-zinc-100 overflow-hidden font-sans bg-grid relative selection:bg-cs-red selection:text-white">

      {/* --- CRITICAL OVERLAY --- */}
      {criticalAlert && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-3xl p-4">
            <div className="bg-zinc-800 border-2 border-cs-red shadow-[0_0_100px_rgba(255,45,45,0.4)] max-w-2xl w-full p-8 relative overflow-hidden rounded-lg">
               <div className="absolute top-0 left-0 w-full h-[1px] bg-cs-red animate-scanline"></div>
               <div className="relative z-10 flex flex-col items-center text-center space-y-6">
                  <div className="w-16 h-16 border border-cs-red rounded-full flex items-center justify-center">
                     <svg className="w-8 h-8 text-cs-red" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>
                  <div>
                    <h2 className="text-3xl font-display font-black tracking-tighter uppercase mb-2 text-white">ACTIVE COMPROMISE</h2>
                    <p className="text-cs-red font-mono text-sm tracking-widest uppercase font-bold">INCIDENT: {criticalAlert.incident_id}</p>
                  </div>
                  <div className="grid grid-cols-3 gap-3 w-full text-left">
                     <div className="bg-zinc-700/30 p-4 border border-white/5"><div className="text-[9px] text-zinc-400 uppercase tracking-widest mb-1 font-black">Asset</div><div className="text-sm font-mono font-bold text-white truncate">{criticalAlert.host_name}</div></div>
                     <div className="bg-zinc-700/30 p-4 border border-white/5"><div className="text-[9px] text-zinc-400 uppercase tracking-widest mb-1 font-black">Risk</div><div className="text-sm font-mono font-bold text-cs-red">CRITICAL</div></div>
                     <div className="bg-zinc-700/30 p-4 border border-white/5"><div className="text-[9px] text-zinc-400 uppercase tracking-widest mb-1 font-black">Tactic</div><div className="text-sm font-mono font-bold text-white">LAT_MOV</div></div>
                  </div>
                  <div className="flex gap-4 w-full">
                    <button 
                        onClick={() => {
                            const command = `AUTHORIZE containment protocols for ${criticalAlert.host_name} (${criticalAlert.host_id})`;
                            setCriticalAlert(null);
                            processUserMessage(command);
                        }}
                        className="flex-1 py-4 bg-cs-red hover:bg-white hover:text-cs-red text-white font-black text-sm tracking-widest uppercase transition-all"
                    >
                        Isolate Host
                    </button>
                    <button onClick={() => setCriticalAlert(null)} className="px-6 py-4 glass text-[10px] font-black uppercase tracking-widest">Ignore</button>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* --- SIDEBAR --- */}
      <aside className="hidden xl:flex flex-col w-[24rem] border-r border-cs-border glass z-30 shadow-2xl relative overflow-hidden">

        {/* Compact Header */}
        <div className="p-6 border-b border-cs-border bg-zinc-800">
           <div className="flex flex-col gap-4">
             <div className="flex items-center gap-3 group cursor-default">
                <div className="flex-shrink-0 w-10 h-10 bg-zinc-900 flex items-center justify-center border border-cs-border relative rounded-sm">
                    <div className="w-6 h-6 flex items-center justify-center font-display font-black text-cs-red text-lg">C</div>
                </div>
                <div>
                    <h1 className="text-2xl font-display font-black tracking-tighter leading-none text-white overflow-visible uppercase">Command</h1>
                    <p className="text-[8px] text-cs-red font-black tracking-[0.4em] uppercase mt-1 pl-2 border-l border-cs-red whitespace-nowrap">Tactical Interface</p>
                </div>
             </div>

             {/* Risk Index */}
             <div>
                <div className="flex justify-between items-end mb-1">
                    <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest">Risk Velocity</span>
                    <span className={`text-lg font-mono font-black ${riskScore > 50 ? 'text-cs-red' : 'text-emerald-400'}`}>{riskScore}%</span>
                </div>
                <div className="h-1 w-full bg-zinc-900 rounded-full overflow-hidden">
                    <div 
                        className={`h-full transition-all duration-1000 ease-out ${riskScore > 70 ? 'bg-cs-red' : riskScore > 30 ? 'bg-amber-400' : 'bg-emerald-400'}`}
                        style={{ width: `${riskScore}%` }}
                    ></div>
                </div>
             </div>
           </div>
        </div>

        {/* Compact Metrics */}
        <div className="px-6 py-4 grid grid-cols-3 gap-2">
            <div className="bg-zinc-700/40 p-3 border border-white/5 rounded-sm">
                <div className="text-[8px] text-zinc-400 uppercase font-black tracking-widest mb-0.5">Crit</div>
                <div className="text-xl font-display font-black text-white">{stats.criticalCount}</div>
            </div>
            <div className="bg-zinc-700/40 p-3 border border-white/5 rounded-sm">
                <div className="text-[8px] text-zinc-400 uppercase font-black tracking-widest mb-0.5">Active</div>
                <div className="text-xl font-display font-black text-white">{stats.openIncidents}</div>
            </div>
            <div className="bg-zinc-700/40 p-3 border border-white/5 rounded-sm">
                <div className="text-[8px] text-zinc-400 uppercase font-black tracking-widest mb-0.5">Iso</div>
                <div className="text-xl font-display font-black text-emerald-400">{stats.containedHosts}</div>
            </div>
        </div>

        {/* Playbook Area - Tighter and Scrollable */}
        <div className="flex-1 flex flex-col min-h-0 py-2">
          <div className="px-6 flex justify-between items-center mb-2">
            <h3 className="text-[9px] font-black text-white uppercase tracking-[0.2em] flex items-center gap-1.5">
               <span className="w-1.5 h-3 bg-cs-red rounded-sm"></span> PLAYBOOKS
            </h3>
          </div>

          <div className="flex-1 px-6 pb-4 overflow-y-auto custom-scrollbar">
            <div className="grid grid-cols-2 gap-2">
                {PLAYBOOKS.map((pb) => (
                    <button 
                      key={pb.id} 
                      onClick={() => runPlaybook(pb)}
                      disabled={isProcessing}
                      className={`text-left p-3 bg-zinc-800 border transition-all duration-200 cursor-pointer rounded-sm group relative flex flex-col justify-between h-[65px] ${
                        activePlaybookId === pb.id ? 'border-cs-red bg-cs-red/20' : 'border-white/5 hover:border-cs-red/40 hover:bg-zinc-700'
                      } ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                        <span className="text-[9px] font-mono font-black text-white group-hover:text-cs-red transition-colors truncate">{pb.name}</span>
                        <p className="text-[8px] text-zinc-500 font-medium leading-tight group-hover:text-zinc-400 transition-colors line-clamp-2">{pb.desc}</p>
                    </button>
                ))}
            </div>
          </div>
        </div>

        {/* Global Controls */}
        <div className="p-6 border-t border-cs-border space-y-2 bg-zinc-800">
            <button 
                onClick={() => setMonitoringEnabled(!monitoringEnabled)}
                className={`w-full py-3.5 flex flex-col items-center justify-center gap-0.5 text-[9px] font-black tracking-widest uppercase transition-all duration-300 border rounded-sm ${
                    monitoringEnabled ? 'bg-cs-red border-cs-red text-white' : 'bg-zinc-900 border-zinc-700 text-zinc-400 hover:text-white hover:border-zinc-500'
                }`}
            >
                <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${monitoringEnabled ? 'bg-white animate-pulse' : 'bg-current'}`}></div>
                    {monitoringEnabled ? 'SENTINEL: ON' : 'ACTIVATE SENTINEL'}
                </div>
            </button>
            <div className="flex gap-2">
                <button onClick={() => setIsSettingsOpen(true)} className="flex-1 text-center text-[8px] font-black text-zinc-300 hover:text-white border border-zinc-700 py-2.5 transition-colors uppercase tracking-widest rounded-sm bg-zinc-900">Config</button>
                <button onClick={() => window.location.reload()} className="flex-1 text-center text-[8px] font-black text-zinc-300 hover:text-cs-red border border-zinc-700 py-2.5 transition-colors uppercase tracking-widest rounded-sm bg-zinc-900">Reset</button>
            </div>
        </div>
      </aside>

      {/* --- MAIN COMMAND STREAM --- */}
      <main className="flex-1 flex flex-col relative h-screen bg-zinc-950">

        {/* Stream Header */}
        <header className="px-6 py-4 border-b border-cs-border flex justify-between items-center bg-zinc-800 z-20">
            <div className="flex items-center gap-4">
                <div className="flex flex-col">
                    <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest">Active Link</span>
                    <span className="text-sm font-mono font-bold text-white tracking-tighter uppercase">SECURE_UPLINK</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex flex-col items-end">
                    <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest">Signal</span>
                    <span className="text-[10px] font-mono font-bold text-emerald-400">ACTIVE</span>
                </div>
            </div>
        </header>

        {/* Forensic Output */}
        <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar bg-black/30">
           <div className="max-w-4xl mx-auto w-full pb-32">
               {messages.map((msg) => (
                 <ChatMessage key={msg.id} message={msg} />
               ))}
               <div ref={messagesEndRef} />
           </div>
        </div>

        {/* Input Interface - Significantly Slimmer */}
        <div className="p-6 pt-0 w-full relative z-20">
           <div className="max-w-4xl mx-auto relative group">
              <form onSubmit={handleSendMessage} className="relative bg-zinc-800 border border-zinc-700 hover:border-cs-red/40 transition-all duration-300 flex flex-col shadow-2xl rounded-sm">
                  <div className="flex items-center pr-4">
                      <div className="pl-6 pr-4 text-cs-red font-mono font-black text-xl select-none">$</div>
                      <input
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        disabled={isProcessing}
                        placeholder={isProcessing ? "PROCESSING..." : "ENTER COMMAND..."}
                        className="w-full bg-transparent text-white py-4 px-1 focus:outline-none font-mono text-sm placeholder:text-zinc-600 font-bold tracking-wider"
                        autoFocus
                      />
                      <button 
                        type="submit" 
                        disabled={!input.trim() || isProcessing} 
                        className="p-2 text-zinc-400 hover:text-cs-red transition-all disabled:opacity-0"
                      >
                         <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
                      </button>
                  </div>
                  {isProcessing && <div className="h-[2px] w-full bg-cs-red shadow-[0_0_10px_#ff2d2d]"></div>}
              </form>
              <div className="mt-3 flex justify-between items-center px-2">
                  <div className="flex gap-4 items-center">
                    <div className="text-[9px] text-zinc-500 font-mono tracking-widest uppercase font-bold">COMMAND_UNIT</div>
                    <div className="text-[9px] text-zinc-600 font-mono tracking-widest uppercase font-bold">Latency: 24ms</div>
                  </div>
                  <div className="flex gap-6">
                      <div className="flex items-center gap-2">
                        <span className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">Logic</span>
                        <div className="w-2 h-2 rounded-full bg-emerald-400"></div>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">Sensor</span>
                        <div className="w-2 h-2 rounded-full bg-cs-red"></div>
                      </div>
                  </div>
              </div>
           </div>
        </div>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={(newConfig) => setConfig(newConfig)} />
    </div>
  );
}

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, ToolCallDetails } from '../types';

interface ChatMessageProps {
  message: Message;
}

const ToolStream: React.FC<{ tools: ToolCallDetails[] }> = ({ tools }) => (
  <div className="mb-4 space-y-2 font-mono text-[9px]">
    {tools.map((t, idx) => (
      <div key={idx} className="bg-black/40 border border-white/5 p-3 relative overflow-hidden rounded-sm">
        <div className="absolute top-0 left-0 w-[1.5px] h-full bg-cs-red"></div>
        <div className="flex items-center gap-3">
          <div className={`w-1.5 h-1.5 rounded-full ${t.status === 'pending' ? 'bg-cs-red animate-pulse' : t.status === 'error' ? 'bg-red-500' : 'bg-emerald-400'}`}></div>
          <div className="flex-1 flex justify-between items-center">
             <div className="flex gap-2">
                <span className="text-zinc-600 uppercase tracking-widest font-black">Call:</span>
                <span className="text-white font-bold">{t.functionName}</span>
             </div>
             <div className="flex gap-2">
                <span className="text-zinc-600 uppercase tracking-widest">Args:</span>
                <span className="text-zinc-500 truncate max-w-[120px]">{JSON.stringify(t.args)}</span>
             </div>
          </div>
        </div>
        {t.result && (
            <div className="mt-2 pt-2 border-t border-white/5 text-[8px] text-zinc-500 max-h-32 overflow-y-auto custom-scrollbar">
                <pre>{JSON.stringify(t.result, null, 2)}</pre>
            </div>
        )}
      </div>
    ))}
  </div>
);

export const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const isAlert = message.isAlert;

  if (message.role === 'system') {
    return (
      <div className="flex justify-center my-6">
        <div className="bg-red-600 text-white px-6 py-2 text-[9px] font-black uppercase tracking-[0.3em] shadow-lg">
           {message.content}
        </div>
      </div>
    );
  }

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} group`}>
      <div className={`max-w-[90%] flex gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Compact Avatar */}
        <div className={`flex-shrink-0 w-8 h-8 glass flex items-center justify-center border rounded-sm ${
            isUser ? 'border-cs-border' : 
            isAlert ? 'border-cs-red shadow-[0_0_10px_rgba(255,0,0,0.2)]' : 'border-cs-border'
        }`}>
          {isUser ? (
             <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
          ) : (
            <div className={`font-display font-black text-sm ${isAlert ? 'text-cs-red' : 'text-white'}`}>C</div>
          )}
        </div>

        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} flex-1 min-w-0`}>
          <div className="flex items-center gap-3 mb-1.5 text-[8px] font-mono tracking-widest uppercase opacity-40 group-hover:opacity-100 transition-opacity">
             <span className={`font-black ${isAlert ? 'text-cs-red' : 'text-white'}`}>
               {isUser ? 'Operator' : isAlert ? 'Alert_Core' : 'CORE_LOGIC'}
             </span>
             <span className="text-zinc-600">
               {message.timestamp.toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
             </span>
          </div>

          <div className={`p-5 glass rounded-sm relative overflow-hidden ${
            isUser 
              ? 'border-white/5' 
              : isAlert 
                ? 'border-cs-red/40 bg-cs-red/5' 
                : 'border-white/5'
          }`}>
            {message.toolCalls && <ToolStream tools={message.toolCalls} />}

            {message.isThinking && !message.content ? (
                 <div className="flex items-center gap-3 py-1 font-mono text-[8px] text-cs-red font-black tracking-widest uppercase">
                    <span className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-cs-red animate-pulse"></div>
                      <div className="w-1.5 h-1.5 bg-cs-red animate-pulse delay-75"></div>
                    </span>
                    ANALYZING...
                 </div>
            ) : (
              <ReactMarkdown 
                className="markdown-content font-sans text-xs text-zinc-300 space-y-4 leading-relaxed"
                components={{
                  h3: ({node, ...props}) => <h3 className="text-[10px] font-black text-white mt-6 mb-2 tracking-widest uppercase flex items-center gap-2 border-l-2 border-cs-red pl-3" {...props} />,
                  ul: ({node, ...props}) => <ul className="space-y-3 my-3" {...props} />,
                  li: ({node, ...props}) => <li className="flex items-start gap-3 text-zinc-400" {...props}><div className="mt-1.5 w-1 h-1 bg-cs-red flex-shrink-0" /> <span className="flex-1">{props.children}</span></li>,
                  code: ({node, ...props}) => <code className="bg-white/5 text-white px-1.5 py-0.5 font-mono text-[10px] border border-white/10 rounded-sm" {...props} />,
                  pre: ({node, ...props}) => <pre className="bg-black/60 p-4 overflow-x-auto text-[10px] font-mono border border-white/5 my-4 text-zinc-400 rounded-sm" {...props} />,
                  p: ({node, ...props}) => <p className="leading-6" {...props} />
                }}
              >
                {message.content}
              </ReactMarkdown>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats, Incident } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### FALCON COMMAND ONLINE
Select a Tactical Playbook or enter a command to begin.`,
  timestamp: new Date()
};

const PLAYBOOKS = [
  { id: 'PB-INFO', name: 'HOST_INFO', cmd: 'Get Host Intelligence: Retrieve full system profile, network interfaces, and last logged-on user for a specific asset.', desc: 'Full asset discovery.' },
  { id: 'PB-LAT', name: 'LATERAL_SWEEP', cmd: 'Perform a Lateral Movement Sweep: Correlate active incidents to find shared user accounts and IP hop-points.', desc: 'Map attack progression.' },
  { id: 'PB-ROOT', name: 'ROOT_CAUSE_AI', cmd: 'Execute Root Cause Analysis: Analyze the process tree and behavioral detections for the most recent critical incident.', desc: 'ML process reconstruction.' },
  { id: 'PB-EXFIL', name: 'EXFIL_HUNTER', cmd: 'Data Exfiltration Hunt: Scan for large network outbound spikes and cloud storage connections.', desc: 'Identify data theft.' },
  { id: 'PB-IDEN', name: 'IDENTITY_AUDIT', cmd: 'Check Identity Integrity: Flag MFA bypasses, abnormal login hours, and new local admin creations.', desc: 'Verify user credentials.' },
  { id: 'PB-PERSIST', name: 'PERSISTENCE', cmd: 'Persistence Audit: Search for new service installations and scheduled tasks across the fleet.', desc: 'Find backdoors.' },
  { id: 'PB-RANS', name: 'RANSOM_WATCH', cmd: 'Ransomware Defense: Check for Shadow Copy deletion and unusual encryption/archiving activity.', desc: 'Prevent encryption.' },
  { id: 'PB-VULN', name: 'VULN_MAPPER', cmd: 'CVE Mapping: Cross-reference active alerts with known critical vulnerabilities (CVEs) on affected hosts.', desc: 'Asset vulnerability link.' },
  { id: 'PB-SCRIPT', name: 'SCRIPT_SCAN', cmd: 'Script Audit: Analyze all PowerShell, WMI, and BITSAdmin execution logs for suspicious obfuscation.', desc: 'Check living-off-the-land.' },
  { id: 'PB-ZERO', name: 'ZERO_TRUST', cmd: 'Zero-Trust Review: Verify conditional access failures and failed MFA attempts for high-value targets.', desc: 'Access integrity.' },
  { id: 'PB-DLP', name: 'DLP_CHECK', cmd: 'Data Loss Audit: Monitor for sensitive file access and removable media usage on flagged assets.', desc: 'Monitor sensitive data.' },
  { id: 'PB-INJECT', name: 'INJECT_HUNT', cmd: 'Code Injection Scan: Search for process hollowing and reflective DLL injection signatures.', desc: 'Find memory-only threats.' },
  { id: 'PB-HYG', name: 'HYGIENE', cmd: 'Fleet Hygiene: Identify assets with outdated sensors or critical patches missing.', desc: 'Assess security posture.' },
  { id: 'PB-CLOUD', name: 'CLOUD_DRIFT', cmd: 'Cloud Security Audit: Analyze drift in container permissions and unusual cloud API calls.', desc: 'Cloud/Container drift.' },
  { id: 'PB-BEACON', name: 'C2_BEACON', cmd: 'C2 Beaconing Hunt: Identify hosts making repetitive, low-volume outbound connections to unknown IPs.', desc: 'Find Command & Control.' }
];

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [monitoringEnabled, setMonitoringEnabled] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [criticalAlert, setCriticalAlert] = useState<Incident | null>(null);

  const [riskScore, setRiskScore] = useState(0);
  const [activePlaybookId, setActivePlaybookId] = useState<string | null>(null);

  const [config, setConfig] = useState<AppConfig>({
    clientId: '',
    clientSecret: '',
    baseUrl: 'https://api.us-2.crowdstrike.com',
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCheckedIncidentRef = useRef<string | null>(null);

  useEffect(() => {
    if (process.env.API_KEY) {
      agentRef.current = new AgentController(process.env.API_KEY, config);
    }
  }, [config]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'auto' });
  }, [messages]);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval> | undefined;
      if (monitoringEnabled && agentRef.current) {
          updateStats();
          interval = setInterval(async () => {
              updateStats();
              checkForNewCriticals();
          }, 15000); 
      }
      return () => { if (interval) clearInterval(interval); };
  }, [monitoringEnabled, config]); 

  const updateStats = async () => {
      if (!agentRef.current) return;
      try {
          const s = await agentRef.current.csService.get_statistics();
          setStats(s);
          const calculatedRisk = Math.min(100, (s.criticalCount * 15) + (s.openIncidents * 2));
          setRiskScore(calculatedRisk);
      } catch (e) { console.error(e); }
  };

  const checkForNewCriticals = async () => {
      if (!agentRef.current) return;
      try {
          const incidents = await agentRef.current.csService.list_incidents({ severity: 'Critical', limit: 1 });
          if (Array.isArray(incidents) && incidents.length > 0) {
              const latest = incidents[0];
              if (lastCheckedIncidentRef.current !== latest.incident_id && latest.status !== 'Closed') {
                  lastCheckedIncidentRef.current = latest.incident_id;
                  setCriticalAlert(latest);

                  setActivePlaybookId('PB-ROOT');
                  const command = `AUTOMATED PLAYBOOK: Perform forensic analysis on critical incident ${latest.incident_id} for host ${latest.host_name}.`;
                  processUserMessage(command, true);
                  setTimeout(() => setActivePlaybookId(null), 5000);
              }
          }
      } catch (e) { }
  };

  const processUserMessage = async (msgText: string, isAutomated: boolean = false) => {
      if (!msgText.trim() || isProcessing || !agentRef.current) return;

      const userMsg: Message = { 
        id: crypto.randomUUID(), 
        role: isAutomated ? 'system' : 'user', 
        content: msgText, 
        timestamp: new Date() 
      };

      setMessages(prev => [...prev, userMsg]);
      setInput('');
      setIsProcessing(true);

      try {
        await agentRef.current.processMessage(msgText, (updatedMsg) => {
          setMessages(prev => {
              const exists = prev.find(m => m.id === updatedMsg.id);
              if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
              return [...prev, updatedMsg];
          });
        });
        updateStats();
      } catch (err) { console.error(err); } finally { setIsProcessing(false); }
  }

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      processUserMessage(input);
  };

  const runPlaybook = (pb: typeof PLAYBOOKS[0]) => {
      if (isProcessing) return;
      setActivePlaybookId(pb.id);
      processUserMessage(pb.cmd, true);
      setTimeout(() => setActivePlaybookId(null), 3000);
  }

  return (
    <div className="flex h-screen bg-cs-bg text-zinc-100 overflow-hidden font-sans bg-grid relative selection:bg-cs-red selection:text-white">

      {/* --- CRITICAL OVERLAY --- */}
      {criticalAlert && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-3xl p-4">
            <div className="bg-zinc-800 border-2 border-cs-red shadow-[0_0_100px_rgba(255,45,45,0.4)] max-w-2xl w-full p-8 relative overflow-hidden rounded-lg">
               <div className="absolute top-0 left-0 w-full h-[1px] bg-cs-red animate-scanline"></div>
               <div className="relative z-10 flex flex-col items-center text-center space-y-6">
                  <div className="w-16 h-16 border border-cs-red rounded-full flex items-center justify-center">
                     <svg className="w-8 h-8 text-cs-red" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>
                  <div>
                    <h2 className="text-3xl font-display font-black tracking-tighter uppercase mb-2 text-white text-wrap px-4">THREAT_DETECTED</h2>
                    <p className="text-cs-red font-mono text-xs tracking-widest uppercase font-bold">INCIDENT: {criticalAlert.incident_id}</p>
                  </div>
                  <div className="grid grid-cols-3 gap-3 w-full text-left">
                     <div className="bg-zinc-700/30 p-3 border border-white/5"><div className="text-[8px] text-zinc-400 uppercase tracking-widest mb-1 font-black">Asset</div><div className="text-xs font-mono font-bold text-white truncate">{criticalAlert.host_name}</div></div>
                     <div className="bg-zinc-700/30 p-3 border border-white/5"><div className="text-[8px] text-zinc-400 uppercase tracking-widest mb-1 font-black">Severity</div><div className="text-xs font-mono font-bold text-cs-red">CRITICAL</div></div>
                     <div className="bg-zinc-700/30 p-3 border border-white/5"><div className="text-[8px] text-zinc-400 uppercase tracking-widest mb-1 font-black">Tactic</div><div className="text-xs font-mono font-bold text-white">LAT_MOV</div></div>
                  </div>
                  <div className="flex gap-3 w-full">
                    <button 
                        onClick={() => {
                            const command = `AUTHORIZE containment protocols for ${criticalAlert.host_name} (${criticalAlert.host_id})`;
                            setCriticalAlert(null);
                            processUserMessage(command);
                        }}
                        className="flex-1 py-3.5 bg-cs-red hover:bg-white hover:text-cs-red text-white font-black text-xs tracking-widest uppercase transition-all"
                    >
                        Isolate Host
                    </button>
                    <button onClick={() => setCriticalAlert(null)} className="px-6 py-3.5 glass text-[9px] font-black uppercase tracking-widest">Acknowledge</button>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* --- SIDEBAR --- */}
      <aside className="hidden xl:flex flex-col w-[22rem] border-r border-cs-border glass z-30 shadow-2xl relative overflow-hidden">

        {/* Restored Falcon Branding Header */}
        <div className="p-5 border-b border-cs-border bg-zinc-800">
           <div className="flex flex-col gap-3">
             <div className="flex items-center gap-3 group cursor-default">
                <div className="flex-shrink-0 w-10 h-10 bg-zinc-900 flex items-center justify-center border border-cs-border relative rounded-sm">
                    <div className="w-6 h-6 flex items-center justify-center font-display font-black text-cs-red text-xl">F</div>
                </div>
                <div>
                    <h1 className="text-xl font-display font-black tracking-tighter leading-none text-white overflow-visible uppercase">Falcon Command</h1>
                    <p className="text-[8px] text-cs-red font-black tracking-[0.4em] uppercase mt-1 pl-1.5 border-l border-cs-red whitespace-nowrap">Intelligence Core</p>
                </div>
             </div>

             {/* Risk Index */}
             <div>
                <div className="flex justify-between items-end mb-1">
                    <span className="text-[8px] font-black text-zinc-400 uppercase tracking-widest">Risk Velocity</span>
                    <span className={`text-sm font-mono font-black ${riskScore > 50 ? 'text-cs-red' : 'text-emerald-400'}`}>{riskScore}%</span>
                </div>
                <div className="h-1 w-full bg-zinc-900 rounded-full overflow-hidden">
                    <div 
                        className={`h-full transition-all duration-1000 ease-out ${riskScore > 70 ? 'bg-cs-red' : riskScore > 30 ? 'bg-amber-400' : 'bg-emerald-400'}`}
                        style={{ width: `${riskScore}%` }}
                    ></div>
                </div>
             </div>
           </div>
        </div>

        {/* Compact Metrics - Restored Isolated label */}
        <div className="px-5 py-3 grid grid-cols-3 gap-2">
            <div className="bg-zinc-700/40 p-2.5 border border-white/5 rounded-sm">
                <div className="text-[7px] text-zinc-400 uppercase font-black tracking-widest mb-0.5">Crit</div>
                <div className="text-lg font-display font-black text-white">{stats.criticalCount}</div>
            </div>
            <div className="bg-zinc-700/40 p-2.5 border border-white/5 rounded-sm">
                <div className="text-[7px] text-zinc-400 uppercase font-black tracking-widest mb-0.5">Active</div>
                <div className="text-lg font-display font-black text-white">{stats.openIncidents}</div>
            </div>
            <div className="bg-zinc-700/40 p-2.5 border border-white/5 rounded-sm">
                <div className="text-[7px] text-zinc-400 uppercase font-black tracking-widest mb-0.5">Isolated</div>
                <div className="text-lg font-display font-black text-emerald-400">{stats.containedHosts}</div>
            </div>
        </div>

        {/* Playbook Area - Optimized Grid Height */}
        <div className="flex-1 flex flex-col min-h-0 pt-1">
          <div className="px-5 flex justify-between items-center mb-1.5">
            <h3 className="text-[8px] font-black text-white uppercase tracking-[0.2em] flex items-center gap-1.5">
               <span className="w-1.5 h-3 bg-cs-red rounded-sm"></span> PLAYBOOKS
            </h3>
          </div>

          <div className="flex-1 px-5 pb-3 overflow-y-auto custom-scrollbar">
            <div className="grid grid-cols-2 gap-2 pb-2">
                {PLAYBOOKS.map((pb) => (
                    <button 
                      key={pb.id} 
                      onClick={() => runPlaybook(pb)}
                      disabled={isProcessing}
                      className={`text-left p-3 bg-zinc-800 border transition-all duration-200 cursor-pointer rounded-sm group relative flex flex-col justify-between h-[60px] ${
                        activePlaybookId === pb.id ? 'border-cs-red bg-cs-red/20 shadow-[inset_0_0_10px_rgba(255,45,45,0.1)]' : 'border-white/5 hover:border-cs-red/40 hover:bg-zinc-700'
                      } ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                        <span className="text-[8px] font-mono font-black text-white group-hover:text-cs-red transition-colors truncate">{pb.name}</span>
                        <p className="text-[7.5px] text-zinc-500 font-medium leading-tight group-hover:text-zinc-400 transition-colors line-clamp-2">{pb.desc}</p>
                    </button>
                ))}
            </div>
          </div>
        </div>

        {/* Global Controls - Compacted */}
        <div className="p-5 border-t border-cs-border space-y-2 bg-zinc-800">
            <button 
                onClick={() => setMonitoringEnabled(!monitoringEnabled)}
                className={`w-full py-3 flex flex-col items-center justify-center gap-0.5 text-[8px] font-black tracking-widest uppercase transition-all duration-300 border rounded-sm ${
                    monitoringEnabled ? 'bg-cs-red border-cs-red text-white' : 'bg-zinc-900 border-zinc-700 text-zinc-400 hover:text-white hover:border-zinc-500'
                }`}
            >
                <div className="flex items-center gap-2">
                    <div className={`w-1.5 h-1.5 rounded-full ${monitoringEnabled ? 'bg-white animate-pulse' : 'bg-current'}`}></div>
                    {monitoringEnabled ? 'SENTINEL: ON' : 'ACTIVATE SENTINEL'}
                </div>
            </button>
            <div className="flex gap-2">
                <button onClick={() => setIsSettingsOpen(true)} className="flex-1 text-center text-[8px] font-black text-zinc-300 hover:text-white border border-zinc-700 py-2.5 transition-colors uppercase tracking-widest rounded-sm bg-zinc-900">Config</button>
                <button onClick={() => window.location.reload()} className="flex-1 text-center text-[8px] font-black text-zinc-300 hover:text-cs-red border border-zinc-700 py-2.5 transition-colors uppercase tracking-widest rounded-sm bg-zinc-900">Reset</button>
            </div>
        </div>
      </aside>

      {/* --- MAIN COMMAND STREAM --- */}
      <main className="flex-1 flex flex-col relative h-screen bg-zinc-950">

        {/* Stream Header */}
        <header className="px-5 py-3 border-b border-cs-border flex justify-between items-center bg-zinc-800 z-20">
            <div className="flex items-center gap-4">
                <div className="flex flex-col">
                    <span className="text-[8px] font-black text-zinc-400 uppercase tracking-widest">Channel</span>
                    <span className="text-xs font-mono font-bold text-white tracking-tighter uppercase">CORE_UPLINK</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex flex-col items-end">
                    <span className="text-[8px] font-black text-zinc-400 uppercase tracking-widest">Signal</span>
                    <span className="text-[9px] font-mono font-bold text-emerald-400 uppercase">Secure</span>
                </div>
            </div>
        </header>

        {/* Forensic Output */}
        <div className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar bg-black/30">
           <div className="max-w-4xl mx-auto w-full pb-32">
               {messages.map((msg) => (
                 <ChatMessage key={msg.id} message={msg} />
               ))}
               <div ref={messagesEndRef} />
           </div>
        </div>

        {/* Input Interface */}
        <div className="p-5 pt-0 w-full relative z-20">
           <div className="max-w-4xl mx-auto relative group">
              <form onSubmit={handleSendMessage} className="relative bg-zinc-800 border border-zinc-700 hover:border-cs-red/40 transition-all duration-300 flex flex-col shadow-2xl rounded-sm">
                  <div className="flex items-center pr-4">
                      <div className="pl-5 pr-4 text-cs-red font-mono font-black text-lg select-none">$</div>
                      <input
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        disabled={isProcessing}
                        placeholder={isProcessing ? "PROCESSING..." : "ENTER COMMAND..."}
                        className="w-full bg-transparent text-white py-3.5 px-1 focus:outline-none font-mono text-sm placeholder:text-zinc-600 font-bold tracking-wider"
                        autoFocus
                      />
                      <button 
                        type="submit" 
                        disabled={!input.trim() || isProcessing} 
                        className="p-2 text-zinc-400 hover:text-cs-red transition-all disabled:opacity-0"
                      >
                         <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
                      </button>
                  </div>
                  {isProcessing && <div className="h-[1.5px] w-full bg-cs-red shadow-[0_0_10px_#ff2d2d]"></div>}
              </form>
              <div className="mt-2.5 flex justify-between items-center px-2">
                  <div className="flex gap-4 items-center">
                    <div className="text-[8px] text-zinc-500 font-mono tracking-widest uppercase font-bold">FIC_V3_CORE</div>
                    <div className="text-[8px] text-zinc-600 font-mono tracking-widest uppercase font-bold">Latency: 24ms</div>
                  </div>
                  <div className="flex gap-4">
                      <div className="flex items-center gap-1.5">
                        <span className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">Logic</span>
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <span className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">Sensor</span>
                        <div className="w-1.5 h-1.5 rounded-full bg-cs-red"></div>
                      </div>
                  </div>
              </div>
           </div>
        </div>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={(newConfig) => setConfig(newConfig)} />
    </div>
  );
}

