                    <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Network Entropy Index</span>
                    <span className={`text-base font-mono font-black ${riskScore > 60 ? 'text-cs-red animate-pulse' : 'text-emerald-400'}`}>{riskScore.toFixed(1)}%</span>
                </div>
                <div className="h-1.5 w-full bg-black rounded-full overflow-hidden border border-white/5">
                    <div 
                        className={`h-full transition-all duration-1000 ease-out ${riskScore > 70 ? 'bg-cs-red shadow-[0_0_15px_#ff2d2d]' : 'bg-emerald-500 shadow-[0_0_10px_#10b981]'}`}
