import { MCPServer, MCPTool, MCPResponse, AppConfig } from '../types';
import { CrowdStrikeService } from './crowdstrikeService';

/**
 * CrowdStrikeMCPServer
 * Implements the Model Context Protocol (MCP) interface for CrowdStrike Falcon operations.
 */
export class CrowdStrikeMCPServer implements MCPServer {
  private csService: CrowdStrikeService;
  public readonly name = "crowdstrike-falcon-mcp";

  constructor(config: AppConfig) {
    this.csService = new CrowdStrikeService(config);
  }

  async listTools(): Promise<MCPTool[]> {
    return [
      {
        name: 'get_statistics',
        description: 'Fetch global fleet-wide metrics (Critical count, Open incidents, Contained hosts) for the dashboard.',
        inputSchema: { type: 'object', properties: {} }
      },
      {
        name: 'list_incidents',
        description: 'Query security incidents from CrowdStrike Falcon with optional severity filtering.',
        inputSchema: {
          type: 'object',
          properties: {
            severity: { type: 'string', enum: ['Critical', 'High', 'Medium', 'Low'], description: 'Minimum severity code to return.' },
            limit: { type: 'integer', description: 'Maximum number of incidents (default 5).' }
          }
        }
      },
      {
        name: 'get_device_details',
        description: 'Get deep metadata (OS, IP, status) for a specific asset by AID or Hostname.',
        inputSchema: {
          type: 'object',
          properties: { identifier: { type: 'string', description: 'Hostname or Agent ID (AID)' } },
          required: ['identifier']
        }
      },
      {
        name: 'contain_host',
        description: 'Isolate a host from the network at the kernel level. Use only for verified high-threat scenarios.',
        inputSchema: {
          type: 'object',
          properties: { device_id: { type: 'string', description: 'The Host Agent ID (AID)' } },
          required: ['device_id']
        }
      },
      {
        name: 'lift_containment',
        description: 'Restore network access to an isolated host after forensic clearance.',
        inputSchema: {
          type: 'object',
          properties: { device_id: { type: 'string', description: 'The Host Agent ID (AID)' } },
          required: ['device_id']
        }
      },
      {
        name: 'get_detections',
        description: 'Retrieve behavioral detection details, including process command lines and MITRE TTPs.',
        inputSchema: {
          type: 'object',
          properties: { 
            host_id: { type: 'string', description: 'Filter detections by Host AID' },
            limit: { type: 'integer', description: 'Default is 5' }
          }
        }
      }
    ];
  }

  async callTool(name: string, args: any): Promise<MCPResponse> {
    try {
      let result;
      switch (name) {
        case 'get_statistics':
          result = await this.csService.get_statistics();
          break;
        case 'list_incidents':
          result = await this.csService.list_incidents(args);
          break;
        case 'get_device_details':
          result = await this.csService.get_device_details(args);
          break;
        case 'contain_host':
          result = await this.csService.contain_host(args);
          break;
        case 'lift_containment':
          result = await this.csService.lift_containment(args);
          break;
        case 'get_detections':
          result = await this.csService.get_detections(args);
          break;
        default:
          throw new Error(`Tool '${name}' not found on server '${this.name}'`);
      }

      return {
        content: [{ type: 'text', text: JSON.stringify(result, null, 2) }]
      };
    } catch (error: any) {
      return {
        content: [{ type: 'text', text: error.message || 'Unknown tool execution error' }],
        isError: true
      };
    }
  }

  // Exposure for App.tsx to use the service directly for background polling
  public getService() {
    return this.csService;
  }
}

import { GoogleGenAI, Chat, GenerateContentResponse, FunctionDeclaration, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { AppConfig, Message, ToolCallDetails, MCPServer, MCPTool } from "../types";
import { CrowdStrikeMCPServer } from "./mcp";

export class AgentController {
  private genAI: GoogleGenAI;
  private chat: Chat | null = null;
  private mcpServer: CrowdStrikeMCPServer;
  private apiKey: string;
  private initialized: Promise<void>;

  constructor(apiKey: string, config: AppConfig) {
    this.apiKey = apiKey;
    this.genAI = new GoogleGenAI({ apiKey });
    this.mcpServer = new CrowdStrikeMCPServer(config);

    // Initialize session by discovering tools from the MCP server
    this.initialized = this.init();
  }

  private async init() {
    const tools: MCPTool[] = await this.mcpServer.listTools();

    // Convert MCP tool schemas to Gemini FunctionDeclaration format
    const functionDeclarations: FunctionDeclaration[] = tools.map(t => ({
      name: t.name,
      description: t.description,
      parameters: this.convertSchemaToGemini(t.inputSchema)
    }));

    this.chat = this.genAI.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION}\n\nYou are connected to an MCP server: ${this.mcpServer.name}. Use the provided tools to interact with the environment.`,
        tools: [{ functionDeclarations }],
        thinkingConfig: { thinkingBudget: 32768 } 
      }
    });
  }

  private convertSchemaToGemini(schema: any): any {
    // Simple conversion of JSON Schema to Gemini parameters format
    // In a real app, this would be more robust to handle nested objects
    return {
      type: Type.OBJECT,
      properties: Object.keys(schema.properties || {}).reduce((acc: any, key) => {
        const prop = schema.properties[key];
        acc[key] = {
          type: prop.type.toUpperCase() === 'INTEGER' ? Type.INTEGER : 
                prop.type.toUpperCase() === 'NUMBER' ? Type.NUMBER : 
                prop.type.toUpperCase() === 'BOOLEAN' ? Type.BOOLEAN : 
                prop.type.toUpperCase() === 'ARRAY' ? Type.ARRAY : 
                Type.STRING,
          description: prop.description,
          ...(prop.enum ? { enum: prop.enum } : {})
        };
        return acc;
      }, {}),
      required: schema.required || []
    };
  }

  async processMessage(userMessage: string | any[], onUpdate: (msg: Message) => void): Promise<void> {
    await this.initialized;
    if (!this.chat) throw new Error("Agent not initialized");

    try {
      let response = await this.chat.sendMessage({ message: userMessage });

      while (response.functionCalls && response.functionCalls.length > 0) {
        const functionCalls = response.functionCalls;

        const toolDetails: ToolCallDetails[] = functionCalls.map(fc => ({
          functionName: fc.name,
          args: fc.args as Record<string, any>,
          status: 'pending',
          serverName: this.mcpServer.name
        }));

        const tempId = crypto.randomUUID();

        onUpdate({
            id: tempId,
            role: 'model',
            content: '', 
            timestamp: new Date(),
            isThinking: true,
            toolCalls: toolDetails
        });

        const toolParts = await Promise.all(
            functionCalls.map(async (call, index) => {
                const mcpResponse = await this.mcpServer.callTool(call.name, call.args);

                // Map back to result format for UI
                let parsedResult;
                try {
                  parsedResult = JSON.parse(mcpResponse.content[0].text);
                } catch {
                  parsedResult = { text: mcpResponse.content[0].text };
                }

                toolDetails[index].result = parsedResult;
                toolDetails[index].status = mcpResponse.isError ? 'error' : 'success';

                return {
                    functionResponse: {
                        name: call.name,
                        response: { result: parsedResult },
                        id: call.id
                    }
                };
            })
        );

        onUpdate({
            id: tempId,
            role: 'model',
            content: '', 
            timestamp: new Date(),
            isThinking: true,
            toolCalls: toolDetails
        });

        response = await this.chat.sendMessage({ message: toolParts });
      }

      onUpdate({
        id: crypto.randomUUID(),
        role: 'model',
        content: response.text || "Diagnostic output generated.",
        timestamp: new Date(),
        isThinking: false
      });

    } catch (error: any) {
      console.error("Agent MCP Logic Failure:", error);
      onUpdate({
        id: crypto.randomUUID(),
        role: 'system',
        content: `LOGIC_FAIL: ${error.message || 'CORE_STABILITY_ERROR'}`,
        timestamp: new Date(),
        isThinking: false
      });
    }
  }

  public get csService() {
    return this.mcpServer.getService();
  }
}

