}

import { AppConfig, SecurityStats } from '../types';

export class CrowdStrikeService {
  private config: AppConfig;
  private token: string | null = null;
  private tokenExpiry: number = 0;

  constructor(config: AppConfig) {
    this.config = config;
  }

  private getRequestUrl(endpoint: string): string {
    const fullUrl = `${this.config.baseUrl}${endpoint}`;
    if (this.config.proxyUrl) {
      // Logic for common proxies like local-cors-proxy or cloudflare workers
      return `${this.config.proxyUrl.replace(/\/$/, '')}/${fullUrl.replace(/^https?:\/\//, '')}`;
    }
    return fullUrl;
  }

  async testConnection(): Promise<boolean> {
    await this.getAccessToken();
    return true;
  }

  private async getAccessToken(): Promise<string> {
    if (this.token && Date.now() < this.tokenExpiry) {
      return this.token;
    }

    if (!this.config.clientId || !this.config.clientSecret) {
      throw new Error("Missing Credentials");
    }

    const body = new URLSearchParams();
    body.append('client_id', this.config.clientId);
    body.append('client_secret', this.config.clientSecret);

    const url = this.getRequestUrl('/oauth2/token');

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body
      });

      if (!response.ok) {
        throw new Error(`Auth Failed (${response.status})`);
      }

      const data = await response.json();
      this.token = data.access_token;
      this.tokenExpiry = Date.now() + (data.expires_in * 1000) - 60000;
      return this.token!;
    } catch (e: any) {
      if (!this.config.proxyUrl) {
        throw new Error("Direct API access blocked by CORS. Please configure a Proxy URL in Settings.");
      }
      throw e;
    }
  }

  private async fetchAPI(endpoint: string, method: string = 'GET', body?: any) {
    const token = await this.getAccessToken();
    const url = this.getRequestUrl(endpoint);

    const response = await fetch(url, {
      method,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: body ? JSON.stringify(body) : undefined
    });

    if (!response.ok) {
      if (response.status === 403) throw new Error(`Access Denied: Check API Scopes for ${endpoint}`);
      throw new Error(`API Error ${response.status}`);
    }

    return response.json();
  }

  async get_statistics(): Promise<SecurityStats> {
    if (!this.config.clientId) return { criticalCount: 0, openIncidents: 0, containedHosts: 0, lastUpdated: new Date() };
    try {
      const critRes = await this.fetchAPI('/incidents/queries/incidents/v1?filter=severity_code:>=80&limit=1');
      const totalRes = await this.fetchAPI('/incidents/queries/incidents/v1?filter=status:[20,30]&limit=1');
      return {
        criticalCount: critRes.meta?.pagination?.total || 0,
        openIncidents: totalRes.meta?.pagination?.total || 0,
        containedHosts: 0,
        lastUpdated: new Date()
      };
    } catch (e) {
      return { criticalCount: 0, openIncidents: 0, containedHosts: 0, lastUpdated: new Date() };
    }
  }

  async list_incidents(args: any) {
    const queryUrl = `/incidents/queries/incidents/v1?limit=${args.limit || 5}&sort=created_timestamp.desc`;
    const queryRes = await this.fetchAPI(queryUrl);
    if (!queryRes.resources?.length) return [];
    const detailsRes = await this.fetchAPI(`/incidents/entities/incidents/GET/v1`, 'POST', { ids: queryRes.resources });
    return detailsRes.resources || [];
  }

  async get_device_details(args: { identifier: string }) {
    const detailsRes = await this.fetchAPI(`/devices/entities/devices/v2`, 'POST', { ids: [args.identifier] });
    return detailsRes.resources?.[0] || { error: "Host not found" };
  }

  async contain_host(args: { device_id: string }) {
    return await this.fetchAPI(`/devices/entities/devices-actions/v2?action_name=contain`, 'POST', { ids: [args.device_id] });
  }

  async lift_containment(args: { device_id: string }) {
    return await this.fetchAPI(`/devices/entities/devices-actions/v2?action_name=lift_containment`, 'POST', { ids: [args.device_id] });
  }

  async get_detections(args: { host_id?: string; limit?: number }) {
    let filter = args.host_id ? `&filter=device.device_id:'${args.host_id}'` : "";
    const queryRes = await this.fetchAPI(`/detects/queries/detects/v1?limit=${args.limit || 5}${filter}`);
    if (!queryRes.resources?.length) return [];
    const detailsRes = await this.fetchAPI(`/detects/entities/summaries/GET/v1`, 'POST', { ids: queryRes.resources });
    return detailsRes.resources || [];
  }
}

import { GoogleGenAI, Chat, FunctionDeclaration, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Message, ToolCallDetails, MCPServer, MCPTool } from "../types";

export class AgentController {
  private genAI: GoogleGenAI;
  private chat: Chat | null = null;
  private servers: MCPServer[] = [];
  private initialized: Promise<void>;

  constructor(apiKey: string, servers: MCPServer[]) {
    this.genAI = new GoogleGenAI({ apiKey });
    this.servers = servers;
    this.initialized = this.init();
  }

  private async init() {
    let allFunctionDeclarations: FunctionDeclaration[] = [];

    for (const server of this.servers) {
      const tools: MCPTool[] = await server.listTools();
      const declarations = tools.map(t => ({
        name: t.name,
        description: `[${server.name}] ${t.description}`,
        parameters: this.convertSchemaToGemini(t.inputSchema)
      }));
      allFunctionDeclarations = [...allFunctionDeclarations, ...declarations];
    }

    this.chat = this.genAI.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION}\n\nYou are an MCP-native agent. Tools are provided by the following servers: ${this.servers.map(s => s.name).join(', ')}.`,
        tools: [{ functionDeclarations: allFunctionDeclarations }],
        thinkingConfig: { thinkingBudget: 32768 } 
      }
    });
  }

  private convertSchemaToGemini(schema: any): any {
    return {
      type: Type.OBJECT,
      properties: Object.keys(schema.properties || {}).reduce((acc: any, key) => {
        const prop = schema.properties[key];
        acc[key] = {
          type: prop.type?.toUpperCase() === 'INTEGER' ? Type.INTEGER : 
                prop.type?.toUpperCase() === 'NUMBER' ? Type.NUMBER : 
                prop.type?.toUpperCase() === 'BOOLEAN' ? Type.BOOLEAN : 
                prop.type?.toUpperCase() === 'ARRAY' ? Type.ARRAY : Type.STRING,
          description: prop.description,
          ...(prop.enum ? { enum: prop.enum } : {})
        };
        return acc;
      }, {}),
      required: schema.required || []
    };
  }

  async processMessage(userMessage: string | any[], onUpdate: (msg: Message) => void): Promise<void> {
    await this.initialized;
    if (!this.chat) throw new Error("Agent disconnected");

    try {
      let response = await this.chat.sendMessage({ message: userMessage });

      while (response.functionCalls?.length) {
        const functionCalls = response.functionCalls;
        const toolDetails: ToolCallDetails[] = functionCalls.map(fc => ({
          functionName: fc.name,
          args: fc.args as Record<string, any>,
          status: 'pending'
        }));

        const turnId = crypto.randomUUID();
        onUpdate({ id: turnId, role: 'model', content: '', timestamp: new Date(), isThinking: true, toolCalls: toolDetails });

        const toolParts = await Promise.all(
          functionCalls.map(async (call, index) => {
            // Find the server that owns this tool
            const server = this.servers.find(s => s.callTool); 
            const mcpResponse = await server!.callTool(call.name, call.args);

            let parsedResult;
            try { parsedResult = JSON.parse(mcpResponse.content[0].text); } catch { parsedResult = mcpResponse.content[0].text; }

            toolDetails[index].result = parsedResult;
            toolDetails[index].status = mcpResponse.isError ? 'error' : 'success';
            toolDetails[index].serverName = server?.name;

            return {
              functionResponse: { name: call.name, response: { result: parsedResult }, id: call.id }
            };
          })
        );

        onUpdate({ id: turnId, role: 'model', content: '', timestamp: new Date(), isThinking: true, toolCalls: toolDetails });
        response = await this.chat.sendMessage({ message: toolParts });
      }

      onUpdate({
        id: crypto.randomUUID(),
        role: 'model',
        content: response.text || "Investigation complete.",
        timestamp: new Date(),
        isThinking: false
      });
    } catch (error: any) {
      onUpdate({ id: crypto.randomUUID(), role: 'system', content: `CRITICAL_EXCEPTION: ${error.message}`, timestamp: new Date() });
    }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';
import { CrowdStrikeMCPServer } from './services/mcp';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### AETHER SECURITY CORE READY
MCP Infrastructure initialized. CrowdStrike Falcon server detected.

How can I assist your investigation today?`,
  timestamp: new Date()
};

export const CommandLogo = ({ size = 24, className = "" }) => (
  <svg width={size} height={size} viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <path d="M20 4L34 11V29L20 36L6 29V11L20 4Z" stroke="#ff2d2d" strokeWidth="1.5" strokeLinejoin="round"/>
    <circle cx="20" cy="20" r="2.5" fill="#ff2d2d"><animate attributeName="opacity" values="0.3;1;0.3" dur="2s" repeatCount="indefinite" /></circle>
  </svg>
);

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [apiState, setApiState] = useState<'IDLE' | 'STABLE' | 'ERROR'>('IDLE');

  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('aether_config');
    return saved ? JSON.parse(saved) : {
      clientId: '',
      clientSecret: '',
      baseUrl: 'https://api.crowdstrike.com',
      proxyUrl: ''
    };
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (process.env.API_KEY && config.clientId) {
      const csServer = new CrowdStrikeMCPServer(config);
      agentRef.current = new AgentController(process.env.API_KEY, [csServer]);
      setApiState('STABLE');
      updateStats(csServer);
    }
  }, [config]);

  const updateStats = async (server: CrowdStrikeMCPServer) => {
    try {
      const s = await server.getService().get_statistics();
      setStats(s);
    } catch (e) { setApiState('ERROR'); }
  };

  const processUserMessage = async (msgText: string) => {
    if (!msgText.trim() || isProcessing || !agentRef.current) return;
    setMessages(prev => [...prev, { id: crypto.randomUUID(), role: 'user', content: msgText, timestamp: new Date() }]);
    setInput('');
    setIsProcessing(true);
    try {
      await agentRef.current.processMessage(msgText, (updatedMsg) => {
        setMessages(prev => {
          const exists = prev.find(m => m.id === updatedMsg.id);
          if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
          return [...prev, updatedMsg];
        });
      });
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="flex h-screen bg-cs-bg text-zinc-100 overflow-hidden font-sans relative">
      <div className="absolute inset-0 pointer-events-none bg-grid opacity-10"></div>

      {/* Sidebar */}
      <aside className="hidden xl:flex flex-col w-80 border-r border-cs-border glass z-30">
        <div className="p-8 border-b border-cs-border bg-black/40">
           <div className="flex items-center gap-4">
              <CommandLogo size={32} />
              <h1 className="text-xl font-black tracking-tighter text-white uppercase italic">AETHER</h1>
           </div>
        </div>
        <div className="p-6 grid grid-cols-2 gap-3">
            <div className="bg-zinc-800/40 p-4 border border-white/5 rounded">
                <div className="text-[8px] text-zinc-500 uppercase font-black mb-1">CRITICAL</div>
                <div className="text-xl font-display font-black text-cs-red">{stats.criticalCount}</div>
            </div>
            <div className="bg-zinc-800/40 p-4 border border-white/5 rounded">
                <div className="text-[8px] text-zinc-500 uppercase font-black mb-1">OPEN</div>
                <div className="text-xl font-display font-black text-white">{stats.openIncidents}</div>
            </div>
        </div>
        <div className="flex-1 p-6 space-y-2 overflow-y-auto">
           <button onClick={() => processUserMessage("Analyze recent incidents")} className="w-full text-left p-3 text-[10px] font-bold uppercase tracking-widest bg-zinc-900 border border-white/5 hover:border-cs-red/40 transition-all">Triage Incidents</button>
           <button onClick={() => processUserMessage("Check host health")} className="w-full text-left p-3 text-[10px] font-bold uppercase tracking-widest bg-zinc-900 border border-white/5 hover:border-cs-red/40 transition-all">Host Audit</button>
        </div>
        <div className="p-6 border-t border-cs-border">
            <button onClick={() => setIsSettingsOpen(true)} className="w-full py-3 text-[10px] font-black uppercase tracking-widest border border-zinc-700 hover:text-white transition-all">Settings</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative h-screen bg-[#050507]">
        <header className="px-8 py-4 border-b border-cs-border flex justify-between items-center bg-black/80 backdrop-blur-xl z-20">
            <span className="text-[10px] font-mono font-bold text-white tracking-widest uppercase flex items-center gap-2">
                <span className={`w-2 h-2 rounded-full ${apiState === 'STABLE' ? 'bg-emerald-500 animate-pulse' : 'bg-cs-red'}`}></span>
                {apiState === 'STABLE' ? 'MCP_STABLE' : 'MCP_OFFLINE'}
            </span>
        </header>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar relative">
           <div className="max-w-4xl mx-auto w-full pb-40">
               {messages.map((msg) => (
                 <ChatMessage key={msg.id} message={msg} />
               ))}
               <div ref={messagesEndRef} />
           </div>
        </div>

        <div className="absolute bottom-0 left-0 w-full p-8 bg-gradient-to-t from-black via-black/90 to-transparent z-40">
           <div className="max-w-4xl mx-auto">
              <form onSubmit={(e) => { e.preventDefault(); processUserMessage(input); }} className="relative">
                  <div className="relative bg-zinc-900/90 border border-zinc-700 focus-within:border-cs-red/40 flex items-center shadow-2xl rounded-lg overflow-hidden transition-all">
                      <div className="pl-6 text-cs-red font-black text-xl select-none">◈</div>
                      <input
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        disabled={isProcessing || apiState !== 'STABLE'}
                        placeholder={apiState !== 'STABLE' ? "CONFIGURE API SETTINGS TO CONNECT..." : "ENTER COMMAND..."}
                        className="w-full bg-transparent text-white py-6 px-4 focus:outline-none font-mono text-sm placeholder:text-zinc-600 font-bold tracking-wider"
                      />
                  </div>
              </form>
           </div>
        </div>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={(c) => { setConfig(c); localStorage.setItem('aether_config', JSON.stringify(c)); }} />
    </div>
  );
}

import React, { useState } from 'react';
import { AppConfig } from '../types';
import { CrowdStrikeService } from '../services/crowdstrikeService';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: AppConfig;
  onSave: (config: AppConfig) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, config, onSave }) => {
  const [formData, setFormData] = useState<AppConfig>(config);
  const [isValidating, setIsValidating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSave = async () => {
      setError(null);
      setIsValidating(true);
      try {
          const tester = new CrowdStrikeService(formData);
          await tester.testConnection();
          onSave(formData);
          onClose();
      } catch (e: any) {
          setError(e.message);
      } finally {
          setIsValidating(false);
      }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn">
      <div className="bg-cs-bg border border-cs-border w-full max-w-2xl shadow-2xl flex flex-col">
        <div className="p-6 border-b border-cs-border bg-black flex items-center justify-between">
            <h2 className="text-xl font-bold text-white uppercase tracking-wider">MCP CONFIGURATION</h2>
        </div>

        <div className="p-8 space-y-6 bg-cs-bg">
            <div className="grid gap-6">
                <div>
                    <label className="block text-[10px] font-black text-cs-dim uppercase mb-2">CORS Proxy URL (Optional)</label>
                    <input type="text" value={formData.proxyUrl || ''} onChange={(e) => setFormData({...formData, proxyUrl: e.target.value})} className="w-full bg-black border border-cs-border text-white px-4 py-3 font-mono text-xs rounded" placeholder="https://your-cors-proxy.workers.dev" />
                    <p className="text-[8px] text-zinc-600 mt-2">Route API calls through a proxy to avoid CORS blocks in the browser.</p>
                </div>
                <div>
                    <label className="block text-[10px] font-black text-cs-dim uppercase mb-2">Client ID</label>
                    <input type="text" value={formData.clientId} onChange={(e) => setFormData({...formData, clientId: e.target.value})} className="w-full bg-black border border-cs-border text-white px-4 py-3 font-mono text-xs rounded" />
                </div>
                <div>
                    <label className="block text-[10px] font-black text-cs-dim uppercase mb-2">Client Secret</label>
                    <input type="password" value={formData.clientSecret} onChange={(e) => setFormData({...formData, clientSecret: e.target.value})} className="w-full bg-black border border-cs-border text-white px-4 py-3 font-mono text-xs rounded" />
                </div>
            </div>
            {error && <div className="text-xs text-cs-red font-mono bg-cs-red/10 p-4 border border-cs-red/20">{error}</div>}
        </div>

        <div className="p-6 border-t border-cs-border flex justify-end gap-4">
            <button onClick={onClose} className="px-6 py-3 text-xs font-bold uppercase">Cancel</button>
            <button onClick={handleSave} disabled={isValidating} className="px-8 py-3 bg-cs-red text-white text-xs font-bold uppercase tracking-widest">
                {isValidating ? 'CONNECTING...' : 'SAVE & CONNECT'}
            </button>
        </div>
      </div>
    </div>
  );
};

