const SENSITIVE_TOOLS = ['contain_host'];

export class AgentController {
  private genAI: GoogleGenAI;
  private chat: Chat | null = null;
  private servers: MCPServer[] = [];
  private initialized: Promise<void>;
  private lastResponse: any = null;

  constructor(apiKey: string, servers: MCPServer[]) {
    this.genAI = new GoogleGenAI({ apiKey });
    this.servers = servers;
    this.initialized = this.init();
  }

  private async init() {
    let allFunctionDeclarations: FunctionDeclaration[] = [];

    for (const server of this.servers) {
      const tools: MCPTool[] = await server.listTools();
      const declarations = tools.map(t => ({
        name: t.name,
        description: `[${server.name}] ${t.description}`,
        parameters: this.convertSchemaToGemini(t.inputSchema)
      }));
      allFunctionDeclarations = [...allFunctionDeclarations, ...declarations];
    }

    this.chat = this.genAI.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION}\n\nYou are an MCP-native agent. Tools are provided by the following servers: ${this.servers.map(s => s.name).join(', ')}.`,
        tools: [{ functionDeclarations: allFunctionDeclarations }],
        thinkingConfig: { thinkingBudget: 32768 } 
      }
    });
  }

  private convertSchemaToGemini(schema: any): any {
    return {
      type: Type.OBJECT,
      properties: Object.keys(schema.properties || {}).reduce((acc: any, key) => {
        const prop = schema.properties[key];
        acc[key] = {
          type: prop.type?.toUpperCase() === 'INTEGER' ? Type.INTEGER : 
                prop.type?.toUpperCase() === 'NUMBER' ? Type.NUMBER : 
                prop.type?.toUpperCase() === 'BOOLEAN' ? Type.BOOLEAN : 
                prop.type?.toUpperCase() === 'ARRAY' ? Type.ARRAY : Type.STRING,
          description: prop.description,
          ...(prop.enum ? { enum: prop.enum } : {})
        };
        return acc;
      }, {}),
      required: schema.required || []
    };
  }

  async processMessage(userMessage: string | any[], onUpdate: (msg: Message) => void): Promise<void> {
    await this.initialized;
    if (!this.chat) throw new Error("Agent disconnected");

    try {
      let response: GenerateContentResponse = await this.chat.sendMessage({ message: userMessage });
      await this.handleResponse(response, onUpdate);
    } catch (error: any) {
      onUpdate({ id: crypto.randomUUID(), role: 'system', content: `CRITICAL_EXCEPTION: ${error.message}`, timestamp: new Date() });
    }
  }

  private async handleResponse(response: GenerateContentResponse, onUpdate: (msg: Message) => void): Promise<void> {
    this.lastResponse = response;

    if (response.functionCalls?.length) {
      const functionCalls = response.functionCalls;
      const toolDetails: ToolCallDetails[] = functionCalls.map(fc => ({
        id: fc.id,
        functionName: fc.name,
        args: fc.args as Record<string, any>,
        status: SENSITIVE_TOOLS.includes(fc.name) ? 'awaiting_approval' : 'pending'
      }));

      const turnId = crypto.randomUUID();
      onUpdate({ id: turnId, role: 'model', content: '', timestamp: new Date(), isThinking: true, toolCalls: toolDetails });

      // If any tool requires approval, we stop here and wait for UI to call resumeWithApproval
      if (toolDetails.some(t => t.status === 'awaiting_approval')) {
        return;
      }

      await this.executeTools(toolDetails, turnId, onUpdate);
    } else {
      onUpdate({
        id: crypto.randomUUID(),
        role: 'model',
        content: response.text || "Investigation complete.",
        timestamp: new Date(),
        isThinking: false
      });
    }
  }

  async resumeWithApproval(turnId: string, approved: boolean, onUpdate: (msg: Message) => void): Promise<void> {
    if (!this.lastResponse || !this.lastResponse.functionCalls) return;

    const functionCalls = this.lastResponse.functionCalls;
    const toolDetails: ToolCallDetails[] = functionCalls.map((fc: any) => ({
      id: fc.id,
      functionName: fc.name,
      args: fc.args as Record<string, any>,
      status: approved ? 'pending' : 'denied'
    }));

    if (!approved) {
      const toolResponses = functionCalls.map((call: any) => ({
        functionResponse: { name: call.name, response: { result: "Action denied by user." }, id: call.id }
      }));
      const nextResponse = await this.chat!.sendMessage({ message: toolResponses });
      await this.handleResponse(nextResponse, onUpdate);
      return;
    }

    await this.executeTools(toolDetails, turnId, onUpdate);
  }

  private async executeTools(toolDetails: ToolCallDetails[], turnId: string, onUpdate: (msg: Message) => void) {
    const toolParts = await Promise.all(
      toolDetails.map(async (detail, index) => {
        const server = this.servers.find(s => s.callTool); 
        const mcpResponse = await server!.callTool(detail.functionName, detail.args);

        let parsedResult;
        try { parsedResult = JSON.parse(mcpResponse.content[0].text); } catch { parsedResult = mcpResponse.content[0].text; }

        toolDetails[index].result = parsedResult;
        toolDetails[index].status = mcpResponse.isError ? 'error' : 'success';
        toolDetails[index].serverName = server?.name;

        return {
          functionResponse: { name: detail.functionName, response: { result: parsedResult }, id: detail.id }
        };
      })
    );

    onUpdate({ id: turnId, role: 'model', content: '', timestamp: new Date(), isThinking: true, toolCalls: toolDetails });
    const response = await this.chat!.sendMessage({ message: toolParts });
    await this.handleResponse(response, onUpdate);
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { AgentController } from './services/agent';
import { Message, AppConfig, SecurityStats } from './types';
import { ChatMessage } from './components/ChatMessage';
import { SettingsModal } from './components/SettingsModal';
import { CrowdStrikeMCPServer } from './services/mcp';

const INITIAL_MESSAGE: Message = {
  id: 'init-1',
  role: 'model',
  content: `### AETHER SECURITY CORE READY
MCP Infrastructure initialized. CrowdStrike Falcon server detected.

**Autonomous Threat Monitor** is now active. I will alert you to new critical detections.`,
  timestamp: new Date()
};

export const CommandLogo = ({ size = 24, className = "" }) => (
  <svg width={size} height={size} viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <path d="M20 4L34 11V29L20 36L6 29V11L20 4Z" stroke="#ff2d2d" strokeWidth="1.5" strokeLinejoin="round"/>
    <circle cx="20" cy="20" r="2.5" fill="#ff2d2d"><animate attributeName="opacity" values="0.3;1;0.3" dur="2s" repeatCount="indefinite" /></circle>
  </svg>
);

export default function App() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [stats, setStats] = useState<SecurityStats>({ openIncidents: 0, criticalCount: 0, containedHosts: 0, lastUpdated: new Date() });
  const [apiState, setApiState] = useState<'IDLE' | 'STABLE' | 'ERROR'>('IDLE');

  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('aether_config');
    return saved ? JSON.parse(saved) : {
      clientId: '',
      clientSecret: '',
      baseUrl: 'https://api.crowdstrike.com',
      proxyUrl: ''
    };
  });

  const agentRef = useRef<AgentController | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastCritCount = useRef<number>(0);

  // Initialize Agent
  useEffect(() => {
    if (process.env.API_KEY && config.clientId) {
      const csServer = new CrowdStrikeMCPServer(config);
      agentRef.current = new AgentController(process.env.API_KEY, [csServer]);
      setApiState('STABLE');
      updateStats(csServer);
    }
  }, [config]);

  // Autonomous Polling Loop (30 seconds)
  useEffect(() => {
    const interval = setInterval(() => {
      if (apiState === 'STABLE' && agentRef.current) {
        const csServer = new CrowdStrikeMCPServer(config);
        updateStats(csServer);
      }
    }, 30000);
    return () => clearInterval(interval);
  }, [apiState, config]);

  const updateStats = async (server: CrowdStrikeMCPServer) => {
    try {
      const s = await server.getService().get_statistics();
      setStats(s);

      // Auto-Alert Logic
      if (s.criticalCount > lastCritCount.current && lastCritCount.current > 0) {
        const alertMsg: Message = {
          id: crypto.randomUUID(),
          role: 'system',
          isAlert: true,
          content: `CRITICAL THREAT DETECTED: ${s.criticalCount - lastCritCount.current} new incident(s) since last check.`,
          timestamp: new Date()
        };
        setMessages(prev => [...prev, alertMsg]);
      }
      lastCritCount.current = s.criticalCount;
    } catch (e) { setApiState('ERROR'); }
  };

  const processUserMessage = async (msgText: string) => {
    if (!msgText.trim() || isProcessing || !agentRef.current) return;
    setMessages(prev => [...prev, { id: crypto.randomUUID(), role: 'user', content: msgText, timestamp: new Date() }]);
    setInput('');
    setIsProcessing(true);
    try {
      await agentRef.current.processMessage(msgText, (updatedMsg) => {
        setMessages(prev => {
          const exists = prev.find(m => m.id === updatedMsg.id);
          if (exists) return prev.map(m => m.id === updatedMsg.id ? updatedMsg : m);
          return [...prev, updatedMsg];
        });
      });
    } finally { setIsProcessing(false); }
  };

  const handleToolApproval = async (turnId: string, approved: boolean) => {
    if (!agentRef.current || isProcessing) return;
    setIsProcessing(true);
    try {
      await agentRef.current.resumeWithApproval(turnId, approved, (updatedMsg) => {
        setMessages(prev => prev.map(m => m.id === updatedMsg.id ? updatedMsg : m));
      });
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="flex h-screen bg-cs-bg text-zinc-100 overflow-hidden font-sans relative">
      <div className="absolute inset-0 pointer-events-none bg-grid opacity-10"></div>

      {/* Sidebar */}
      <aside className="hidden xl:flex flex-col w-80 border-r border-cs-border glass z-30">
        <div className="p-8 border-b border-cs-border bg-black/40">
           <div className="flex items-center gap-4">
              <CommandLogo size={32} />
              <h1 className="text-xl font-black tracking-tighter text-white uppercase italic">AETHER</h1>
           </div>
        </div>
        <div className="p-6 grid grid-cols-2 gap-3">
            <div className={`p-4 border border-white/5 rounded transition-colors ${stats.criticalCount > 0 ? 'bg-cs-red/10' : 'bg-zinc-800/40'}`}>
                <div className="text-[8px] text-zinc-500 uppercase font-black mb-1">CRITICAL</div>
                <div className={`text-xl font-display font-black ${stats.criticalCount > 0 ? 'text-cs-red animate-pulse' : 'text-zinc-500'}`}>{stats.criticalCount}</div>
            </div>
            <div className="bg-zinc-800/40 p-4 border border-white/5 rounded">
                <div className="text-[8px] text-zinc-500 uppercase font-black mb-1">OPEN</div>
                <div className="text-xl font-display font-black text-white">{stats.openIncidents}</div>
            </div>
        </div>
        <div className="flex-1 p-6 space-y-2 overflow-y-auto">
           <p className="text-[8px] text-zinc-600 font-black uppercase tracking-[0.2em] mb-4">TACTICAL SHORTCUTS</p>
           <button onClick={() => processUserMessage("Analyze the most recent critical incident")} className="w-full text-left p-3 text-[10px] font-bold uppercase tracking-widest bg-zinc-900 border border-white/5 hover:border-cs-red/40 transition-all">Start Triage</button>
           <button onClick={() => processUserMessage("Run a health check across the fleet")} className="w-full text-left p-3 text-[10px] font-bold uppercase tracking-widest bg-zinc-900 border border-white/5 hover:border-cs-red/40 transition-all">Host Audit</button>
        </div>
        <div className="p-6 border-t border-cs-border">
            <button onClick={() => setIsSettingsOpen(true)} className="w-full py-3 text-[10px] font-black uppercase tracking-widest border border-zinc-700 hover:text-white transition-all">Settings</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative h-screen bg-[#050507]">
        <header className="px-8 py-4 border-b border-cs-border flex justify-between items-center bg-black/80 backdrop-blur-xl z-20">
            <span className="text-[10px] font-mono font-bold text-white tracking-widest uppercase flex items-center gap-2">
                <span className={`w-2 h-2 rounded-full ${apiState === 'STABLE' ? 'bg-emerald-500 animate-pulse' : 'bg-cs-red'}`}></span>
                {apiState === 'STABLE' ? 'MONITOR_ACTIVE' : 'MCP_OFFLINE'}
            </span>
            <div className="flex gap-4">
              <span className="text-[10px] font-mono text-zinc-500 uppercase tracking-widest">
                Last Updated: {stats.lastUpdated.toLocaleTimeString()}
              </span>
            </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar relative">
           <div className="max-w-4xl mx-auto w-full pb-40">
               {messages.map((msg) => (
                 <ChatMessage 
                    key={msg.id} 
                    message={msg} 
                    onToolApproval={(approved) => handleToolApproval(msg.id, approved)}
                 />
               ))}
               <div ref={messagesEndRef} />
           </div>
        </div>

        <div className="absolute bottom-0 left-0 w-full p-8 bg-gradient-to-t from-black via-black/90 to-transparent z-40">
           <div className="max-w-4xl mx-auto">
              <form onSubmit={(e) => { e.preventDefault(); processUserMessage(input); }} className="relative">
                  <div className="relative bg-zinc-900/90 border border-zinc-700 focus-within:border-cs-red/40 flex items-center shadow-2xl rounded-lg overflow-hidden transition-all">
                      <div className="pl-6 text-cs-red font-black text-xl select-none">◈</div>
                      <input
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        disabled={isProcessing || apiState !== 'STABLE'}
                        placeholder={apiState !== 'STABLE' ? "CONFIGURE API SETTINGS TO CONNECT..." : "ENTER COMMAND..."}
                        className="w-full bg-transparent text-white py-6 px-4 focus:outline-none font-mono text-sm placeholder:text-zinc-600 font-bold tracking-wider"
                      />
                  </div>
              </form>
           </div>
        </div>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={(c) => { setConfig(c); localStorage.setItem('aether_config', JSON.stringify(c)); }} />
    </div>
  );
}

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message, ToolCallDetails } from '../types';
import { CommandLogo } from '../App';

interface ChatMessageProps {
  message: Message;
  onToolApproval?: (approved: boolean) => void;
  onLiftContainment?: (deviceId: string) => void;
}

const ToolStream: React.FC<{ tools: ToolCallDetails[], onApproval?: (approved: boolean) => void, onLift?: (id: string) => void }> = ({ tools, onApproval, onLift }) => (
  <div className="mb-6 space-y-3 font-mono">
    {tools.map((t, idx) => {
      const isContained = t.result?.status === 'contained' || (Array.isArray(t.result) && t.result.some((r: any) => r.status === 'contained'));
      const deviceId = t.result?.device_id || (Array.isArray(t.result) ? t.result.find((r: any) => r.status === 'contained')?.device_id : null);
      const isError = t.status === 'error';
      const isPendingApproval = t.status === 'awaiting_approval';

      return (
        <div key={idx} className={`bg-black/60 border rounded relative overflow-hidden group shadow-2xl transition-all duration-300 ${isPendingApproval ? 'border-orange-500/50 shadow-orange-500/10' : 'border-white/5'}`}>
          <div className={`absolute top-0 left-0 w-[3px] h-full ${isPendingApproval ? 'bg-orange-500 animate-pulse' : isError ? 'bg-red-600' : 'bg-cs-red'}`}></div>
          <div className="p-4">
            <div className="flex items-center justify-between gap-4 mb-2">
               <div className="flex items-center gap-3">
                  <div className={`w-2 h-2 rounded-full ${t.status === 'pending' ? 'bg-cs-red animate-ping' : isPendingApproval ? 'bg-orange-500 animate-pulse' : isError ? 'bg-red-600' : 'bg-emerald-500'}`}></div>
                  <span className={`text-[10px] uppercase tracking-[0.2em] font-black ${isPendingApproval ? 'text-orange-500' : 'text-zinc-500'}`}>
                    {isPendingApproval ? 'Authorization Required' : t.serverName ? `MCP::${t.serverName}` : 'Executing Tactical Tool'}
                  </span>
               </div>
               <span className="text-[10px] text-white font-bold bg-white/5 px-2 py-0.5 rounded border border-white/5 uppercase">{t.functionName}</span>
            </div>

            <div className="text-[9px] text-zinc-600 uppercase flex gap-2 overflow-hidden mb-3">
               <span className="flex-shrink-0">Params:</span>
               <span className="truncate text-zinc-500">{JSON.stringify(t.args)}</span>
            </div>

            {isPendingApproval && onApproval && (
               <div className="mt-4 p-4 bg-orange-500/5 border border-orange-500/20 rounded-sm">
                  <p className="text-[10px] text-orange-200 font-black uppercase tracking-widest mb-4">Warning: Kernel-Level Host Isolation Requested</p>
                  <div className="flex gap-3">
                    <button 
                      onClick={() => onApproval(true)}
                      className="flex-1 bg-orange-500 text-black font-black text-[9px] py-3 rounded-sm uppercase tracking-widest hover:bg-orange-400 transition-colors shadow-lg"
                    >
                      Authorize Action
                    </button>
                    <button 
                      onClick={() => onApproval(false)}
                      className="px-6 border border-white/10 text-white font-black text-[9px] py-3 rounded-sm uppercase tracking-widest hover:bg-white/5 transition-colors"
                    >
                      Deny
                    </button>
                  </div>
               </div>
            )}

            {t.result && (
                <div className="mt-2 bg-zinc-950/80 p-4 border border-white/5 rounded-sm">
                   <div className="max-h-60 overflow-y-auto custom-scrollbar font-mono text-[10px] leading-relaxed text-zinc-300">
                      {isError ? (
                        <div className="text-red-400 font-black uppercase">ERROR: {t.result.error || 'Execution failed'}</div>
                      ) : (
                        <pre className="whitespace-pre-wrap">{JSON.stringify(t.result, null, 2)}</pre>
                      )}
                   </div>

                   {isContained && deviceId && onLift && (
                    <div className="mt-4 pt-4 border-t border-white/5">
                        <button 
                          onClick={() => onLift(deviceId)}
                          className="w-full bg-emerald-500/10 hover:bg-emerald-500 hover:text-black border border-emerald-500/40 text-emerald-400 py-3 rounded-sm font-black uppercase tracking-[0.3em] text-[9px] transition-all duration-300 shadow-[0_0_20px_rgba(16,185,129,0.1)]"
                        >
                          Lift Isolation
                        </button>
                    </div>
                  )}
                </div>
            )}
          </div>
        </div>
      );
    })}
  </div>
);

export const ChatMessage: React.FC<ChatMessageProps> = ({ message, onToolApproval, onLiftContainment }) => {
  const isUser = message.role === 'user';
  const isAlert = message.isAlert;

  if (message.role === 'system') {
    return (
      <div className={`flex justify-center my-10 relative ${isAlert ? 'animate-pulse' : ''}`}>
        <div className="absolute inset-0 flex items-center">
            <div className={`w-full border-t border-dashed ${isAlert ? 'border-cs-red/40' : 'border-zinc-800'}`}></div>
        </div>
        <div className={`${isAlert ? 'bg-cs-red' : 'bg-zinc-800'} text-white px-8 py-2.5 text-[10px] font-black uppercase tracking-[0.4em] shadow-2xl rounded-sm relative z-10 italic`}>
           {message.content}
        </div>
      </div>
    );
  }

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
      <div className={`max-w-[95%] xl:max-w-[85%] flex gap-6 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar Section */}
        <div className="flex flex-col items-center gap-2 flex-shrink-0">
          <div className={`w-10 h-10 glass flex items-center justify-center border-2 rounded transition-all duration-500 ${
              isUser ? 'border-cs-border hover:border-white' : 
              isAlert ? 'border-cs-red shadow-[0_0_20px_rgba(255,45,45,0.4)] animate-pulse' : 'border-cs-border'
          }`}>
            {isUser ? (
               <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
            ) : (
              <CommandLogo size={20} />
            )}
          </div>
        </div>

        {/* Message Content Section */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} flex-1 min-w-0`}>
          <div className="flex items-center gap-4 mb-2 text-[10px] font-mono tracking-widest uppercase opacity-60">
             <span className={`font-black ${isAlert ? 'text-cs-red' : 'text-white'}`}>
               {isUser ? 'ANALYST' : isAlert ? 'SYSTEM ALERT' : 'AETHER INTEL'}
             </span>
             <span className="text-zinc-600 font-bold">
               {message.timestamp.toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
             </span>
          </div>

          <div className={`p-6 glass rounded relative overflow-hidden shadow-2xl ${
            isUser 
              ? 'border-white/5 bg-white/5' 
              : isAlert 
                ? 'border-cs-red/40 bg-cs-red/5' 
                : 'border-white/5 bg-zinc-900/40'
          }`}>
            {message.toolCalls && <ToolStream tools={message.toolCalls} onApproval={onToolApproval} onLift={onLiftContainment} />}

            {message.isThinking && !message.content ? (
                 <div className="flex items-center gap-4 py-2 font-mono text-[10px] text-cs-red font-black tracking-[0.3em] uppercase">
                    <div className="flex gap-2">
                      <div className="w-2 h-2 bg-cs-red animate-pulse"></div>
                      <div className="w-2 h-2 bg-cs-red animate-pulse delay-75"></div>
                      <div className="w-2 h-2 bg-cs-red animate-pulse delay-150"></div>
                    </div>
                    Syncing MCP Server...
                 </div>
            ) : (
              <div className="markdown-content font-sans text-[13px] text-zinc-300 space-y-5 leading-relaxed">
                <ReactMarkdown 
                  components={{
                    h3: ({node, ...props}) => <h3 className="text-[11px] font-black text-white mt-8 mb-3 tracking-[0.2em] uppercase flex items-center gap-3 border-l-4 border-cs-red pl-4 py-0.5 bg-gradient-to-r from-cs-red/10 to-transparent" {...props} />,
                    ul: ({node, ...props}) => <ul className="space-y-4 my-4" {...props} />,
                    li: ({node, ...props}) => <li className="flex items-start gap-4 text-zinc-400" {...props}><div className="mt-2 w-1.5 h-1.5 bg-cs-red rotate-45 flex-shrink-0" /> <span className="flex-1">{props.children}</span></li>,
                    code: ({node, ...props}) => {
                      const content = String(props.children);
                      const isTTP = /T\d{4}/.test(content);
                      return (
                        <code className={`${isTTP ? 'bg-cs-red/20 text-cs-red font-black border-cs-red/40 px-2' : 'bg-white/5 text-white px-1.5'} py-0.5 font-mono text-[11px] border rounded-sm`} {...props} />
                      );
                    },
                    pre: ({node, ...props}) => <pre className="bg-black/80 p-5 overflow-x-auto text-[11px] font-mono border border-white/5 my-6 text-zinc-400 rounded-sm shadow-inner" {...props} />,
                    blockquote: ({node, ...props}) => <blockquote className="border-l-4 border-emerald-500 bg-emerald-500/5 p-4 my-4 text-emerald-400 font-mono text-[11px] uppercase tracking-widest" {...props} />,
                    p: ({node, ...props}) => <p className="leading-7" {...props} />
                  }}
                >
                  {message.content}
                </ReactMarkdown>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};
